const O={};globalThis.P=(en,ar)=>({en,ar});try{globalThis["D"]=O["D"]=({"sites":[{"id":"hegra","n":"Hegra (Mada’in Salih)","na":"الحِجر (مدائن صالح)","c":"archaeological","s":"Nabataean tomb city · World Heritage","lat":26.7917,"lng":37.9542,"p":"Nabataean to Roman","dr":"1st century BC – 2nd century AD","el":"111 monumental tombs cut into sandstone","ic":"wall","era":"H","t0":2100,"t1":1850,"te":"The southern city of the Nabataeans","ta":"مدينة الأنباط الجنوبية","se":"111 tombs carved into sandstone outcrops, with dated inscriptions from 1 BC to AD 74","sa":"111 مقبرة منحوتة في نتوءات الحجر الرملي، بنقوش مؤرخة من 1 ق.م إلى 74 م","desc":"The largest Nabataean site south of Petra: 111 monumental tombs cut into sandstone outcrops around a now-vanished city, 94 of them decorated, with dated inscriptions running from 1 BC to AD 74. Qasr al-Bint, the largest, is about 16 m high. Water came from wells and cisterns in the plain. Rome annexed the Nabataean kingdom in AD 106 and a Roman garrison is attested at Hegra. Inscribed in 2008 as Saudi Arabia's first World Heritage site; excavated by the Saudi-French Madâ'in Sâlih Archaeological Project since 2008.","sig":"The best-preserved Nabataean tombs anywhere, and the only ones with a run of dated inscriptions.","ex":"Saudi-French Madâ’in Sâlih Archaeological Project (L. Nehmé) 2008 onwards; Royal Commission for AlUla","disc":["Tombs dated by inscription from 1 BC to AD 74","Roman garrison after AD 106"],"refs":["UNESCO World Heritage Centre. Hegra Archaeological Site (al-Hijr / Madā ͐ in Ṣāliḥ) (ref. 1293), inscribed 2008.","Nehmé, L. (ed.) (2015). Les tombeaux nabatéens de Hégra. Académie des Inscriptions et Belles-Lettres."],"conf":"","ev":"","an":"","val":""},{"id":"mustatils","n":"Mustatils of the Nafud","na":"مستطيلات النفود","c":"archaeological","s":"Neolithic stone monuments · AlUla–Khaybar","lat":25.7,"lng":39.3,"p":"Neolithic","dr":"c. 5300 – 5000 BC","el":"Over 1,000 rectangles, 20 – 620 m long","ic":"platform","era":"P","t0":7300,"t1":7000,"te":"A thousand rectangles in the desert","ta":"ألف مستطيل في الصحراء","se":"Stone enclosures up to 620 m long, built 7,000 years ago and holding cattle horns as offerings","sa":"حظائر حجرية يصل طولها إلى 620 م، بُنيت قبل 7,000 عام وتضم قرون ماشية كقرابين","desc":"Long rectangular stone structures, 20 to 620 m in length, found by the thousand across north-west Arabia from the Nafud to the lava fields of Khaybar: more than 1,000 are recorded over about 200,000 km². Excavation of a mustatil near AlUla found a chamber with cattle, sheep and gazelle horns placed as offerings around a standing stone, radiocarbon-dated to about 5300–5000 BC, making them among the oldest large-scale monuments in the world. Their builders were cattle herders of a wetter Arabia.","sig":"Older than the pyramids and Stonehenge, and until 2021 almost unknown outside Arabia.","ex":"Aerial Archaeology in the Kingdom of Saudi Arabia (University of Western Australia) and Royal Commission for AlUla, 2018 onwards","disc":["Cattle horns deposited around a standing stone","Radiocarbon dates of c. 5300–5000 BC"],"refs":["Thomas, H., Kennedy, M. A., Dalton, M. et al. (2021). The mustatils: cult and monumentality in Neolithic north-western Arabia. Antiquity 95(381), 605–626.","Kennedy, M. A. et al. (2023). Cult, herding and pilgrimage in the Late Neolithic of north-west Arabia. PLOS ONE 18(3)."],"conf":"","ev":"","an":"","val":""},{"id":"at-turaif","n":"At-Turaif District, Diriyah","na":"حي الطريف، الدرعية","c":"archaeological","s":"Najdi mud-brick capital · World Heritage","lat":24.734,"lng":46.573,"p":"Islamic (First Saudi State)","dr":"15th century – 1818","el":"Salwa Palace and mud-brick city on Wadi Hanifah","ic":"wall","era":"H","t0":575,"t1":208,"te":"A capital made of earth","ta":"عاصمة من تراب","se":"The mud-brick heart of the First Saudi State, on a bend of Wadi Hanifah","sa":"قلب الدولة السعودية الأولى من الطوب الطيني، على منعطف وادي حنيفة","desc":"A walled district of mud brick on the edge of Wadi Hanifah, settled in the 15th century and from 1727 the capital of the First Saudi State until an Ottoman-Egyptian siege took it in 1818. Salwa Palace, the Imam Mohammed bin Saud Mosque and houses of the Najdi style, with thick adobe walls, triangular openings and tamarisk roofs, survive. Inscribed in 2010 under criteria (iv), (v) and (vi) and restored as part of the Diriyah project.","sig":"The finest surviving example of Najdi architecture and the birthplace of the Saudi state.","ex":"Diriyah Gate Development Authority; Saudi Commission for Tourism and National Heritage","disc":["Najdi mud-brick style with triangular vents","Capital 1727–1818"],"refs":["UNESCO World Heritage Centre. At-Turaif District in ad-Dir’iyah (ref. 1329), inscribed 2010.","Diriyah Gate Development Authority. At-Turaif UNESCO World Heritage Site."],"conf":"","ev":"","an":"","val":""},{"id":"al-ahsa-oasis","n":"Al-Ahsa Oasis","na":"واحة الأحساء","c":"archaeological","s":"Largest oasis in the world · World Heritage","lat":25.4294,"lng":49.6219,"p":"Neolithic to present","dr":"c. 5000 BC – today","el":"2.5 million date palms on 85 km²","ic":"well","era":"H","t0":7000,"t1":0,"te":"Two and a half million palms","ta":"مليونان ونصف من النخيل","se":"Springs feed the largest oasis on Earth, farmed without a break since the Neolithic","sa":"عيون تغذي أكبر واحة على الأرض، زُرعت دون انقطاع منذ العصر الحجري الحديث","desc":"An oasis of about 85.4 km² in the Eastern Province with some 2.5 million date palms watered by more than 280 artesian springs from the Neogene aquifer. Twelve components, including gardens, canals, springs, Jawatha mosque and Qasr Ibrahim, record settlement from the Neolithic to the present. Inscribed in 2018 under criteria (iii), (iv) and (v) as the world's largest oasis.","sig":"A cultural landscape that shows how people have farmed one spring-fed place for seven thousand years.","ex":"Saudi Commission for Tourism and National Heritage; Al-Ahsa Municipality","disc":["More than 280 springs","Continuous farming since the Neolithic"],"refs":["UNESCO World Heritage Centre. Al-Ahsa Oasis, an Evolving Cultural Landscape (ref. 1563), inscribed 2018.","Saudipedia. Al-Ahsa Oasis."],"conf":"","ev":"","an":"","val":""},{"id":"hail-rock-art","n":"Rock Art of Jubbah and Shuwaymis","na":"فنون صخرية في جبة والشويمس","c":"archaeological","s":"Ten thousand years of carvings · World Heritage","lat":28.0106,"lng":40.9131,"p":"Neolithic to Islamic","dr":"c. 8000 BC – 1st millennium AD","el":"Petroglyphs above a vanished lake 20 km long","ic":"eye","era":"P","t0":10000,"t1":1500,"te":"Pictures beside a lake that dried","ta":"صور بجوار بحيرة جفّت","se":"Life-size humans, cattle and lions carved over 10,000 years on cliffs that once overlooked a lake","sa":"بشر وماشية وأسود بحجمها الطبيعي نُقشت على مدى 10,000 عام على جروف أطلّت يومًا على بحيرة","desc":"Two clusters of petroglyphs in Ha'il: Jabal Umm Sinman at Jubbah, above the bed of a Holocene lake about 20 by 5 km, and Jabal al-Manjor and Raat at Shuwaymis. The oldest carvings, of life-size people and wild animals, date back about 10,000 years; later panels show cattle herding, horses, camels and Thamudic inscriptions. Inscribed in 2015 under criteria (i) and (iii).","sig":"One of the largest and longest sequences of rock art in the world.","ex":"Saudi Commission for Tourism and National Heritage; Palaeodeserts Project (Max Planck Institute)","disc":["Palaeolake 20 × 5 km at Jubbah","Carvings spanning 10,000 years"],"refs":["UNESCO World Heritage Centre. Rock Art in the Hail Region of Saudi Arabia (ref. 1472), inscribed 2015.","Guagnin, M. et al. (2017). Rock art provides new evidence on the biogeography of kudu, wild dromedary, aurochs and African wild ass in the early and middle Holocene of north-western Arabia. Journal of Biogeography 44, 2071–2081."],"conf":"","ev":"","an":"","val":""},{"id":"al-faw","n":"Qaryat al-Faw","na":"قرية الفاو","c":"archaeological","s":"Capital of Kinda · World Heritage","lat":19.7649,"lng":45.1634,"p":"Pre-Islamic","dr":"4th century BC – c. AD 300","el":"Walled town, market, temples and 17 wells","ic":"caravan","era":"H","t0":2350,"t1":1700,"te":"The city at the edge of the Empty Quarter","ta":"المدينة على حافة الربع الخالي","se":"A caravan capital with wall paintings, a market and temples, found under the sand at Wadi al-Dawasir","sa":"عاصمة قوافل بجدارياتها وسوقها ومعابدها، وُجدت تحت الرمل في وادي الدواسر","desc":"The capital of the kingdom of Kinda on the caravan route between Yemen and the Gulf, at a gap in the Tuwaiq escarpment facing the Rub' al Khali. Excavated by King Saud University from 1972, it has a walled market, houses with wall paintings, five temples, tombs and 17 wells, with South Arabian inscriptions and bronzes. Inscribed on 27 July 2024 as the Cultural Landscape of Al-Faw Archaeological Area.","sig":"The most complete pre-Islamic town in central Arabia and its first painted interiors.","ex":"King Saud University (A. R. al-Ansary) 1972 onwards; Heritage Commission and Saudi-French mission","disc":["Wall paintings of a feasting man","17 wells for a desert town"],"refs":["UNESCO World Heritage Centre. Cultural Landscape of Al-Faw Archaeological Area (ref. 1712), inscribed 2024.","al-Ansary, A. R. (1982). Qaryat al-Fau: a portrait of pre-Islamic civilisation in Saudi Arabia. University of Riyadh."],"conf":"","ev":"","an":"","val":""},{"id":"hima","n":"Ḥimā Cultural Area","na":"منطقة حمى الثقافية","c":"archaeological","s":"Rock art and ancient wells · World Heritage","lat":18.2505,"lng":44.4515,"p":"Neolithic to Islamic","dr":"c. 5000 BC – today","el":"Bir Hima wells in use for 3,000 years","ic":"well","era":"P","t0":7000,"t1":0,"te":"Seven thousand years of travellers","ta":"سبعة آلاف عام من المسافرين","se":"Rock art and inscriptions in many scripts beside wells that caravans still use","sa":"فنون صخرية ونقوش بخطوط عدة بجوار آبار ما زالت القوافل تستخدمها","desc":"A mountainous area north of Najran on one of Arabia's oldest caravan routes, with 34 rock-art sites carved over some 7,000 years: hunting, animals, plants and people, and inscriptions in Musnad, Thamudic, Greek and early Arabic. The Bir Hima wells have supplied travellers for about 3,000 years and still flow. Inscribed in 2021 under criterion (iii).","sig":"A roadside archive of every script that passed through southern Arabia.","ex":"Saudi Heritage Commission; Saudi-French Najran mission","disc":["Inscriptions in several scripts","Wells in continuous use"],"refs":["UNESCO World Heritage Centre. Ḥimā Cultural Area (ref. 1619), inscribed 2021.","Heritage Commission, Saudi Arabia. Hima Cultural Area nomination file."],"conf":"","ev":"","an":"","val":""},{"id":"tarout-island","n":"Tarout Island","na":"جزيرة تاروت","c":"archaeological","s":"Dilmun-era island of Qatif","lat":26.571,"lng":50.056,"p":"Ubaid to Islamic","dr":"c. 5000 BC – today","el":"Castle mound on 7,000 years of layers","ic":"island","era":"P","t0":7000,"t1":0,"te":"Seven thousand years under one castle","ta":"سبعة آلاف عام تحت قلعة واحدة","se":"An island off Qatif settled since about 5000 BC, with a Dilmun past and a Portuguese fort","sa":"جزيرة قبالة القطيف سُكنت منذ نحو 5000 ق.م، بماضٍ دلموني وحصن برتغالي","desc":"An island about 6 km off Qatif, joined to it by causeways, inhabited since about 5000 BC. Pottery of c. 4500 and 3000 BC was excavated by a Danish team in 1968, tombs date to c. 2000 BC and a 94 cm stone statue of a man, probably Sumerian in style, is in the National Museum in Riyadh. The island was a centre of the Dilmun world; Tarout Castle stands on the mound, with a Portuguese fort of 1515–1521 nearby.","sig":"The oldest continuously inhabited place on the Saudi Gulf coast.","ex":"Danish expedition (G. Bibby) 1968; Saudi Department of Antiquities","disc":["Stone statue in Sumerian style","Ubaid pottery of c. 4500 BC"],"refs":["Wikipedia contributors (2026). Tarout Island, citing Bibby, G. (1969) Looking for Dilmun.","Saudipedia. Tarout Island."],"conf":"","ev":"","an":"","val":""},{"id":"thaj","n":"Thaj","na":"ثاج","c":"archaeological","s":"Hellenistic walled city, possibly Gerrha","lat":26.868,"lng":48.715,"p":"Hellenistic","dr":"c. 300 BC – AD 300","el":"Stone city wall and a gold funerary mask","ic":"sword","era":"H","t0":2300,"t1":1700,"te":"The girl with the golden mask","ta":"الفتاة ذات القناع الذهبي","se":"A walled Hellenistic city 90 km inland from Jubail, where a child was buried with a mask of gold","sa":"مدينة هلنستية مسوّرة على بُعد 90 كم من الجبيل، دُفنت فيها طفلة بقناع من الذهب","desc":"A Hellenistic city about 90 km west of Jubail enclosed by a stone wall, settled from about 300 BC to AD 300 and possibly earlier; many scholars think it the site of Gerrha, the rich trading city Strabo described. A Danish mission (1968), a Saudi-British team (1983) and Saudi excavations from 2000 found houses, coins and, in a tomb, a young girl buried with a gold funerary mask, gloves and jewellery, now in the National Museum.","sig":"The richest burial of pre-Islamic eastern Arabia and the best candidate for lost Gerrha.","ex":"Danish expedition 1968; Saudi-UK 1983; Saudi Department of Antiquities 2000–2006; Saudi-French Thaj mission 2016 onwards","disc":["Gold funerary mask of a child","City wall of dressed stone"],"refs":["Wikipedia contributors (2026). Thaj, citing Potts, D. T. (1990) The Arabian Gulf in Antiquity.","Asharq Al-Awsat (1 March 2017). Thaj: land of gold treasures in Saudi Arabia."],"conf":"","ev":"","an":"","val":""},{"id":"jubail-church","n":"Jubail Church","na":"كنيسة الجبيل","c":"archaeological","s":"Church of the East, 4th–7th century","lat":27.03,"lng":49.6,"p":"Late pre-Islamic / early Islamic","dr":"4th – 7th century AD","el":"Nave, sanctuary and two carved crosses","ic":"platform","era":"H","t0":1650,"t1":1350,"te":"A church found at a picnic","ta":"كنيسة وُجدت في نزهة","se":"Picnickers found a buried church in 1986; its carved crosses still mark the doorway","sa":"عثر متنزهون على كنيسة مدفونة عام 1986؛ وما زالت صلبانها المنحوتة تعلّم المدخل","desc":"A church of the Church of the East near Jubail, found by picnickers in 1986 and excavated by the Saudi Department of Antiquities in 1987. Two crosses are carved either side of the doorway between nave and sanctuary. Its date is debated between the 4th and 7th centuries; it belongs to the chain of Christian communities along the Gulf known from Sir Bani Yas, Kharg and Failaka. The site is fenced and the excavation unpublished.","sig":"Evidence of the Christian communities of the Gulf coast before Islam.","ex":"Saudi Department of Antiquities 1987","disc":["Two carved crosses in situ","Found by chance in 1986"],"refs":["Wikipedia contributors (2026). Jubail Church.","Langfeldt, J. A. (1994). Recently discovered early Christian monuments in northeastern Arabia. Arabian Archaeology and Epigraphy 5, 32–60."],"conf":"","ev":"","an":"","val":""},{"id":"dadan-jabal-ikmah","n":"Dadan and Jabal Ikmah","na":"دادان وجبل عكمة","c":"archaeological","s":"Lihyanite capital and open-air library","lat":26.65,"lng":37.93,"p":"Dadanite – Lihyanite","dr":"c. 800 – 100 BC","el":"450 inscriptions on one canyon","ic":"eye","era":"H","t0":2800,"t1":2100,"te":"A library carved in a canyon","ta":"مكتبة منقوشة في وادٍ","se":"The capital of Dadan and Lihyan, and a canyon with 450 inscriptions in old Arabian scripts","sa":"عاصمة دادان ولحيان، ووادٍ فيه 450 نقشًا بالخطوط العربية القديمة","desc":"Dadan, in the AlUla valley, was the capital of the Dadanite and then Lihyanite kingdoms of the 1st millennium BC: a town below a cliff of tombs, some guarded by carved lions, and a sanctuary with statues of kings. Nearby Jabal Ikmah holds about 450 inscriptions in Dadanitic, an ancient North Arabian script, most from the second half of the 1st millennium BC, recording rituals, taxes and names. Jabal Ikmah joined UNESCO's Memory of the World Register in May 2023.","sig":"The largest concentration of Dadanitic texts, a step on the road to Arabic.","ex":"King Saud University 2004 onwards; Royal Commission for AlUla with French CNRS mission","disc":["Lion tombs of Dadan","450 inscriptions on Jabal Ikmah"],"refs":["Arab News (24 May 2023). AlUla’s Jabal Ikmah listed on UNESCO’s Memory of the World Register.","Royal Commission for AlUla. Dadan and Jabal Ikmah heritage sites."],"conf":"","ev":"","an":"","val":""},{"id":"historic-jeddah","n":"Historic Jeddah (Al-Balad)","na":"جدة التاريخية (البلد)","c":"archaeological","s":"Coral-stone port · World Heritage","lat":21.4858,"lng":39.1875,"p":"Islamic","dr":"7th century – today","el":"Tower houses of coral stone with wooden rawashin","ic":"boat","era":"H","t0":1380,"t1":0,"te":"A city built from the reef","ta":"مدينة بُنيت من الشعاب","se":"The port of Makkah since the 7th century, its tall houses built of coral stone and screened in wood","sa":"ميناء مكة منذ القرن السابع، بيوته العالية من حجر المرجان ومزيّنة بالرواشين","desc":"The old walled town of Jeddah, made the port of Makkah by Caliph Uthman in the 7th century, grew rich on pilgrim and Indian Ocean trade. Its tower houses are built of coral stone quarried from the Red Sea reef and faced with large wooden rawashin, with mosques, ribats and suqs between them. About a third of the original walled city is inscribed (2014, criteria ii, iv, vi); the Ministry of Culture began a large restoration in 2021.","sig":"The last Red Sea merchant town still standing in coral stone.","ex":"Ministry of Culture, Jeddah Historic District Program","disc":["Houses of reef coral","Port of Makkah since the 7th century"],"refs":["UNESCO World Heritage Centre. Historic Jeddah, the Gate to Makkah (ref. 1361), inscribed 2014.","Jeddah Historic District Program. Explore Historic Jeddah."],"conf":"","ev":"","an":"","val":""},{"id":"umm-jirsan","n":"Umm Jirsan Lava Tube","na":"كهف أم جرسان","c":"archaeological","s":"Herders’ shelter in a lava tube","lat":25.586,"lng":39.754,"p":"Neolithic to Bronze Age","dr":"c. 8000 – 5000 BC and later","el":"1.5 km of underground passage","ic":"flame","era":"P","t0":10000,"t1":4000,"te":"People who lived in a lava tube","ta":"أناس عاشوا في أنبوب بركاني","se":"The first excavated lava tube in Arabia sheltered herders for thousands of years","sa":"أول أنبوب بركاني يُنقَّب في الجزيرة العربية آوى الرعاة آلاف السنين","desc":"A lava tube about 1.5 km long in the Harrat Khaybar lava field, the first in Arabia to be excavated. Stone tools, animal bones and charcoal show repeated use from about 10,000 to 7,000 years ago and into the Bronze Age by groups herding cattle, sheep and goats; rock art at the entrance shows herding and dogs, and human remains record diets that gained fruit and cereals when oasis farming arrived. Published in PLOS ONE in 2024.","sig":"The first proof that people used Arabia's lava caves as shelters on the move.","ex":"Max Planck Institute of Geoanthropology, Heritage Commission and Saudi Geological Survey (Stewart et al.)","disc":["Occupation from 10,000 years ago","Rock art of herders with dogs"],"refs":["Stewart, M., Andrieux, E., Blinkhorn, J. et al. (2024). First evidence for human occupation of a lava tube in Arabia. PLOS ONE 19(4).","Max Planck Institute of Geoanthropology (2024). Archaeological insights from the first lava tube excavation in Arabia."],"conf":"","ev":"","an":"","val":""},{"id":"edge-of-the-world","n":"Edge of the World (Jebel Fihrayn)","na":"حافة العالم (جبل فهرين)","c":"geological","s":"Tuwaiq escarpment of Jurassic limestone","lat":24.95,"lng":45.99,"p":"Middle Jurassic","dr":"c. 165 million years ago","el":"Cliffs about 300 m above an ancient sea bed","ic":"cliff","era":"D","t0":165000000,"t1":160000000,"te":"A reef 800 km long","ta":"شعاب بطول 800 كم","se":"The Tuwaiq escarpment is Jurassic sea floor, lifted and cut into cliffs that run 800 km","sa":"جرف طويق قاع بحر جوراسي، رُفع وقُطع إلى جروف تمتد 800 كم","desc":"The Tuwaiq escarpment runs some 800 km through Najd from Qassim to Wadi al-Dawasir, a wall of Middle Jurassic Tuwaiq Mountain limestone up to 600 m high laid down in a shallow sea with coral bioherms. At Jebel Fihrayn, about 100 km north-west of Riyadh, the cliff stands 1,131 m above sea level and drops about 300 m to the plain, with the view that earned it the name Edge of the World. The same limestone holds Callovian corals and, at depth, the reservoirs of the Arab Formation.","sig":"The spine of central Arabia and the outcrop of the rocks that hold its oil.","ex":"Saudi Geological Survey; King Saud University geology","disc":["Jurassic corals in the limestone","Escarpment of 800 km"],"refs":["Wikipedia contributors (2026). Tuwaiq, citing Powers, R. W. et al. (1966) Geology of the Arabian Peninsula: sedimentary geology of Saudi Arabia, USGS Professional Paper 560-D.","El-Sorogy, A. S. et al. (2016). Callovian colonial corals from the Tuwaiq Mountain Limestone of Saudi Arabia. Journal of African Earth Sciences."],"conf":"","ev":"","an":"","val":""},{"id":"harrat-rahat","n":"Harrat Rahat and the 1256 Eruption","na":"حرة رهط وثوران 1256","c":"geological","s":"Lava field that reached Madinah","lat":24.3,"lng":39.78,"p":"Quaternary volcanism","dr":"1256 AD (last eruption)","el":"Lava flow 23 km long, 4 km short of the city","ic":"flame","era":"H","t0":770,"t1":770,"te":"The night the lava came to Madinah","ta":"ليلة وصلت الحمم إلى المدينة","se":"In 1256 a fissure opened and lava flowed 23 km, stopping 4 km from Madinah","sa":"في 1256 انشقّ الأرض وسالت الحمم 23 كم، وتوقفت على بُعد 4 كم من المدينة","desc":"The largest lava field in Saudi Arabia, stretching about 300 km south of Madinah and rising to 1,744 m. In 1256 AD (654 AH) an eruption on its northern edge lasted 52 days, poured out about 0.5 km³ of basalt in a flow 23 km long that stopped 4 km from Madinah, and was recorded by the city's chroniclers; an earlier eruption is dated to AD 641. Earthquake swarms in 1999 and 2009 (at Harrat Lunayyir) show the fields are not extinct.","sig":"The best-documented historic eruption in Arabia, written down by eyewitnesses.","ex":"Saudi Geological Survey; Camp & Roobol (USGS) 1989","disc":["52-day eruption of 1256 AD","Flow stopped 4 km from the city"],"refs":["Camp, V. E. & Roobol, M. J. (1989). The Arabian continental alkali basalt province: Part I. Evolution of Harrat Rahat, Kingdom of Saudi Arabia. GSA Bulletin 101, 71–95.","Saudi Geological Survey. Harrat Rahat volcanic field."],"conf":"","ev":"","an":"","val":""},{"id":"al-wahbah-crater","n":"Al Wahbah Crater","na":"فوهة الوعبة","c":"geological","s":"Maar crater of Harrat Kishb","lat":22.9,"lng":41.14,"p":"Pleistocene","dr":"c. 1.1 million years ago","el":"2.2 km wide, 250 m deep, salt floor","ic":"mudvolc","era":"D","t0":1147000,"t1":1147000,"te":"A bowl blown out by steam","ta":"حفرة نسفها البخار","se":"Rising magma met groundwater and blew a crater 2 km across; salt now floors it","sa":"التقت الصهارة الصاعدة بالمياه الجوفية فنسفت فوهة بعرض 2 كم؛ يغطي قاعها الملح اليوم","desc":"A maar about 2.2 km across and 250 m deep in the Harrat Kishb lava field between Taif and Madinah, formed when basaltic magma met groundwater and exploded through steam. Its floor is a white pan of sodium phosphate and salt crystals; its walls expose the layered tuff and the older lavas. Dated to about 1.15 million years. Once thought a meteorite crater, it is now a popular hike with a trail to the floor.","sig":"The largest and clearest maar crater in Arabia.","ex":"Saudi Geological Survey; King Abdulaziz University","disc":["Phreatomagmatic origin confirmed","Salt floor 250 m down"],"refs":["Abdel Wahab, A., Abul-Maaty, M., Stuart, F. M. et al. (2014). Volcanic history of Al Wahbah maar, Saudi Arabia. Journal of African Earth Sciences 92, 1–13.","Saudi Geological Survey. Al Wahbah Crater."],"conf":"","ev":"","an":"","val":""},{"id":"wabar-craters","n":"Wabar Craters","na":"فوهات وبار","c":"geological","s":"Iron meteorite impact in the Rub’ al Khali","lat":21.5025,"lng":50.4742,"p":"Recent","dr":"Within the last few centuries","el":"Three craters, the largest 116 m","ic":"quake","era":"H","t0":300,"t1":150,"te":"The place of iron","ta":"أرض الحديد","se":"An iron meteorite of more than 3,500 tonnes struck the dunes and left glass and craters that Philby found in 1932","sa":"نيزك حديدي يزيد على 3,500 طن ضرب الكثبان وخلّف زجاجًا وفوهات وجدها فيلبي عام 1932","desc":"A group of impact craters, the largest about 116 m across, in the sands of the Rub' al Khali, reached by H. St John Philby on 2 February 1932 while searching for the lost city of Ubar; the Bedouin called it Al Hadida, the place of iron. An iron meteorite estimated at more than 3,500 tonnes exploded on impact, leaving black glass pellets, bleached impactite with coesite and iron fragments including the 2.2-tonne Camel's Hump now in Riyadh. Thermoluminescence dating puts the fall within the last 250 years or so; the dunes are burying the craters.","sig":"One of the few impact sites on Earth preserved in sand, and among the youngest.","ex":"Philby 1932; Zahid–USGS expeditions (J. C. Wynn, E. M. Shoemaker) 1994–95","disc":["Impact glass and coesite","Age under 250 years"],"refs":["Wynn, J. C. & Shoemaker, E. M. (1998). The day the sands caught fire. Scientific American 279(5), 64–71.","Prescott, J. R., Robertson, G. B., Shoemaker, C., Shoemaker, E. M. & Wynn, J. (2004). Luminescence dating of the Wabar meteorite craters, Saudi Arabia. Journal of Geophysical Research 109."],"conf":"","ev":"","an":"","val":""},{"id":"dammam-no-7","n":"Dammam Well No. 7 (Prosperity Well)","na":"بئر الدمام رقم 7 (بئر الخير)","c":"geological","s":"Where Saudi oil was found, 1938","lat":26.3211,"lng":50.1278,"p":"Jurassic reservoir (Arab Formation)","dr":"3 March 1938","el":"Oil struck at 1,440 m","ic":"oil","era":"N","t0":88,"t1":44,"te":"The well that would not give up","ta":"البئر التي لم تستسلم","se":"After six dry wells, No. 7 found oil at 1,440 m in the Arab Formation and flowed for 44 years","sa":"بعد ست آبار جافة، وجدت البئر رقم 7 النفط على عمق 1,440 م في تكوين العرب وتدفقت 44 عامًا","desc":"On the Dammam Dome, the first six wells drilled by CASOC from 1935 found little. On 3 March 1938 well No. 7, deepened on the advice of geologist Max Steineke, struck oil at 1,440 m in the Jurassic Arab Formation and flowed at over 1,500 barrels a day. It produced about 32 million barrels until it was shut in 1982, and is preserved as a monument in Dhahran. The dome is a salt-cored anticline, the same structure that holds Bahrain's and Qatar's fields.","sig":"The well that started the Saudi oil industry.","ex":"Saudi Aramco; Saudi Geological Survey","disc":["Oil at 1,440 m in the Arab Formation","32 million barrels over 44 years"],"refs":["Saudi Aramco. Dammam No. 7: the Prosperity Well.","Wikipedia contributors (2026). Dammam No. 7, citing Aramco World and Steineke, M. (1938) report to CASOC."],"conf":"","ev":"","an":"","val":""},{"id":"shaybah-dunes","n":"Shaybah Dunes","na":"كثبان شيبة","c":"geological","s":"Dunes 300 m high over an oil field","lat":22.52,"lng":53.96,"p":"Quaternary sands over Jurassic reservoir","dr":"Last 1 million years (dunes); 1968 discovery","el":"Linear dunes up to 333 m, sabkha floors","ic":"dune","era":"N","t0":58,"t1":0,"te":"Sand a hundred storeys high","ta":"رمال بارتفاع مئة طابق","se":"Red dunes 300 m tall in the Empty Quarter, with an oil field found in 1968 beneath them","sa":"كثبان حمراء بارتفاع 300 م في الربع الخالي، تحتها حقل نفط اكتُشف عام 1968","desc":"In the north-east of the Rub' al Khali, about 800 km south of Dhahran, long red dunes rise up to 333 m above floors of sabkha; they belong to the largest continuous sand sea on Earth. Oil was found beneath them by the Shaybah-1 well in 1968, and the field, with about 14 billion barrels of proved reserves, was developed in 1995–98 and reached 1 million barrels a day in 2016. A 637 km² wildlife sanctuary around the plant holds more than 40 Arabian oryx and 70 sand gazelles.","sig":"The tallest dunes of Arabia, and a working oil field in the emptiest place on Earth.","ex":"Saudi Aramco; Saudi Geological Survey (Rub’ al Khali sands)","disc":["Dunes up to 333 m","Sanctuary of 637 km²"],"refs":["Saudipedia. Shaybah Oil Field.","Saudi Aramco. Shaybah: an oasis in the Empty Quarter."],"conf":"","ev":"","an":"","val":""},{"id":"uruq-bani-maarid","n":"‘Uruq Bani Ma’arid","na":"عروق بني معارض","c":"ecology","s":"Oryx reserve on the Empty Quarter · World Heritage","lat":19.5,"lng":45.9,"p":"Living desert","dr":"Protected since 1994 · World Heritage 2023","el":"12,750 km² of dunes and escarpment","ic":"gazelle","era":"N","t0":32,"t1":0,"te":"Where the oryx came home","ta":"حيث عاد المها","se":"The Arabian oryx, extinct in the wild in 1972, was released here in 1995 and now breeds free","sa":"المها العربي، الذي انقرض في البرية عام 1972، أُطلق هنا عام 1995 ويتكاثر حرًا اليوم","desc":"A reserve of 12,750 km² on the western edge of the Rub' al Khali, where the Tuwaiq escarpment meets the sand sea. Protected in 1994, it received the first Arabian oryx released back into the wild in 1995 after the species had been lost from the wild in 1972; it also holds sand gazelle, mountain gazelle, Nubian ibex and about 120 plant species. Inscribed in September 2023 as Saudi Arabia's first natural World Heritage site under criteria (vii) and (ix).","sig":"The largest oryx reintroduction in the world and the first natural World Heritage site of the kingdom.","ex":"National Center for Wildlife; formerly NCWCD","disc":["Oryx reintroduced from 1995","120 plant species in the sand"],"refs":["UNESCO World Heritage Centre. ‘Uruq Bani Ma’arid (ref. 1699), inscribed 2023.","National Center for Wildlife, Saudi Arabia. Uruq Bani Ma’arid Protected Area."],"conf":"","ev":"","an":"","val":""},{"id":"farasan-islands","n":"Farasan Islands","na":"جزر فرسان","c":"ecology","s":"Red Sea archipelago · Biosphere Reserve","lat":16.7,"lng":42.0,"p":"Living reef and islands","dr":"Protected 1989 · Biosphere Reserve 2021","el":"More than 84 islands, 5,408 km²","ic":"island","era":"N","t0":37,"t1":0,"te":"Gazelles on a coral island","ta":"غزلان على جزيرة مرجانية","se":"Eighty-four islands of raised reef, home to Saudi Arabia’s largest gazelle herd, mangroves and nesting seabirds","sa":"أربع وثمانون جزيرة من شعاب مرفوعة، موطن أكبر قطيع غزلان في السعودية، والقرم والطيور البحرية","desc":"An archipelago of more than 84 islands about 42 km off Jazan, built of uplifted coral limestone that stands 10–20 m and locally 75 m above the sea. Protected in 1989 and Saudi Arabia's first UNESCO Biosphere Reserve in September 2021, the 5,408 km² reserve is 90 percent marine: coral reefs, seagrass, three of the Red Sea's thirteen red-mangrove stands, dugong, green and hawksbill turtles, and nesting pink-backed pelicans, sooty falcons and crab-plovers. The islands carry the largest population of the Farasan (idmi) gazelle.","sig":"The richest island ecosystem of the Saudi Red Sea.","ex":"National Center for Wildlife; Khaled bin Sultan Living Oceans Foundation surveys 2006","disc":["Largest gazelle population in the kingdom","Uplifted coral islands"],"refs":["UN Saudi Arabia (2021). Juzur Farasan: first Biosphere Reserve in KSA.","Saudipedia. Farasan Islands Marine Reserve."],"conf":"","ev":"","an":"","val":""},{"id":"jubail-marine-sanctuary","n":"Jubail Marine Wildlife Sanctuary","na":"محمية الجبيل البحرية","c":"ecology","s":"Seagrass, dugong and flamingos on the Gulf","lat":27.083,"lng":49.617,"p":"Living coast","dr":"Established 1990s after the 1991 oil spill","el":"About 2,410 km² of bays and islands","ic":"dolphin","era":"N","t0":35,"t1":0,"te":"A coast that healed","ta":"ساحل تعافى","se":"Hit by the 1991 oil spill, the bays north of Jubail were protected and now hold dugong, turtles and a flamingo colony","sa":"بعد تسرب النفط عام 1991، حُميت الخلجان شمال الجبيل وتضم اليوم الأتوم والسلاحف ومستعمرة فلامنغو","desc":"A protected area of about 2,410 km² of shallow bays, islands and sabkha between Jubail and the Kuwaiti border, the coast most heavily oiled by the 1991 Gulf War spill. Set up by the NCWCD in the early 1990s, it protects seagrass meadows, coral patches, mangroves and mudflats used by several hundred dugong, green and hawksbill turtles, dolphins and a breeding colony of greater flamingos; the Sabkhat al-Fasl lagoons nearby are a Key Biodiversity Area for waterbirds.","sig":"The main recovery site for the Gulf coast after the largest oil spill in history.","ex":"National Center for Wildlife; Royal Commission for Jubail; EU-Gulf War damage assessment 1992","disc":["Several hundred dugong","Flamingo breeding colony"],"refs":["Protected Planet. Jubail Marine Wildlife Sanctuary (WDPA 61786).","Krupp, F. & Abuzinada, A. H. (eds.) (1996). A Marine Wildlife Sanctuary for the Arabian Gulf: environmental research and conservation following the 1991 Gulf War oil spill. NCWCD and Senckenberg."],"conf":"","ev":"","an":"","val":""},{"id":"raydah-juniper","n":"Raydah Reserve and the Asir Junipers","na":"محمية ريدة وعرعر عسير","c":"ecology","s":"Cloud forest of Arabia","lat":18.2,"lng":42.4,"p":"Living forest","dr":"Protected since 1989","el":"Escarpment from 2,800 m to 1,350 m","ic":"wood","era":"N","t0":37,"t1":0,"te":"A forest in the clouds","ta":"غابة في السحاب","se":"Juniper woods between 2,500 and 3,000 m hold the Asir magpie, found nowhere else on Earth","sa":"غابات العرعر بين 2,500 و3,000 م تضم عقعق عسير الذي لا يوجد في أي مكان آخر على الأرض","desc":"About 1,200 ha of the Asir escarpment west of Abha, falling from about 2,800 m to Wadi Jaw at 1,350 m, protected since 1989 for the densest juniper woodland in the kingdom. The junipers grow between 2,500 and 3,000 m where monsoon cloud brings moisture, and shelter most of Arabia's endemic birds, including the Asir magpie, estimated at only about 135 pairs. Drought, grazing and development threaten the trees; Soudah Development has planted some 165,000 native trees in the highlands.","sig":"The only cloud forest of the Arabian Peninsula and the home of its rarest bird.","ex":"National Center for Wildlife; Asir National Park; National Center for Vegetation Cover","disc":["Asir magpie, c. 135 pairs","Junipers up to 255 years old"],"refs":["Birds of Saudi Arabia (J. Babbington). Arabian endemics and the Raydah Protected Area.","Arab News (16 May 2025). How Saudi Arabia is safeguarding biodiversity by restoring its ancient juniper forests."],"conf":"","ev":"","an":"","val":""},{"id":"al-wajh-lagoon","n":"Al Wajh Lagoon","na":"بحيرة الوجه","c":"ecology","s":"Red Sea reef lagoon of 92 islands","lat":25.6,"lng":36.8,"p":"Living reef","dr":"Marine spatial plan 2020","el":"2,081 km² lagoon, 92 islands","ic":"wave","era":"N","t0":6,"t1":0,"te":"Ninety-two islands, nine untouched","ta":"اثنتان وتسعون جزيرة، تسع منها بلا مساس","se":"A reef lagoon planned so that 58 percent is conserved and development covers 5 percent","sa":"بحيرة شعابية خُطط لها بحيث يُحفظ 58% منها ولا يتجاوز العمران 5%","desc":"A lagoon of 2,081 km² enclosed by a barrier reef on the northern Red Sea coast, with 92 islands, coral reefs, seagrass beds and mangroves and species of global conservation concern. In 2020 KAUST scientists led by Carlos Duarte published a marine spatial plan for the Red Sea Project here that conserves 58 percent of the marine area and limits development to about 5 percent, aiming for a 30 percent net conservation gain. The reef corals of the northern Red Sea are among the most heat-tolerant known.","sig":"A test of whether tourism can be built around a reef without losing it.","ex":"KAUST Red Sea Research Center; Red Sea Global","disc":["Marine plan conserving 58% of the lagoon","Corals tolerant of heat"],"refs":["Chalastani, V. I., Manetos, P., Al-Suwailem, A. M. et al. (2020). Reconciling tourism development and conservation outcomes through marine spatial planning for a Saudi Giga-Project in the Red Sea. Frontiers in Marine Science 7, 168.","KAUST News (15 April 2020). Scientific paper details marine spatial planning at Red Sea Project."],"conf":"","ev":"","an":"","val":""},{"id":"tayma-oasis","n":"Tayma Oasis","na":"واحة تيماء","c":"archaeological","s":"Walled oasis city of Nabonidus · Saudi-German excavations","lat":27.63,"lng":38.55,"p":"Bronze Age to Byzantine","dr":"c. 4000 BC – AD 600","el":"City wall of about 15 km","ic":"wall","era":"H","t0":6025,"t1":1400,"te":"The king who left Babylon","ta":"الملك الذي غادر بابل","se":"An oasis ringed by 15 km of wall, where the last king of Babylon lived for ten years","sa":"واحة يحيط بها سور طوله 15 كم، عاش فيها آخر ملوك بابل عشر سنوات","desc":"An oasis city between the Hijaz mountains and the Nafud, with a main mound of more than 200 acres and a sandstone-and-mud-brick wall of just over 15 km enclosing oasis, fields and part of a dried lake; parts of the wall date to 2500–2000 BC and it stood by the end of the second millennium BC. Carnelian bead-making and flint working go back to about 4000 BC, a temple was in use from the 12th to 9th centuries BC, and a 2010 find carried the name of pharaoh Ramesses III, the first pharaonic inscription found in Saudi Arabia. The Babylonian king Nabonidus moved here in 556 BC and stayed about a decade; a sandstone stela showing him was found near the main temple. Saudi-German excavations under the German Archaeological Institute began in 2004.","sig":"The only place outside Mesopotamia where a Babylonian king ruled for a decade, and one of the longest-lived oases in Arabia.","ex":"German Archaeological Institute (R. Eichmann, A. Hausleiter) with the Saudi Commission for Tourism and Antiquities, 2004 onwards; BTU Cottbus wall survey","disc":["Inscription of Ramesses III found 2010","Nabonidus lived here 556–543 BC"],"refs":["Lawler, A. (2018). Searching for Tayma. Archaeology magazine / andrewlawler.com.","Rheidt, K. & Schneider, P. I. BTU Cottbus-Senftenberg. Tayma – Eine nordwestarabische Stadtmauer (project page).","Hausleiter, A. & Eichmann, R. (eds). Taymāʾ I: Archaeological Exploration, Palaeoenvironment, Cultural Contacts. Archaeopress."],"conf":"","ev":"","an":"","val":""},{"id":"marid-castle","n":"Marid Castle, Dumat al-Jandal","na":"قلعة مارد، دومة الجندل","c":"archaeological","s":"Nabataean-founded hill fort · Al-Jawf","lat":29.81,"lng":39.87,"p":"Nabataean to Islamic","dr":"1st century AD – 20th century","el":"Four conical towers about 12 m tall","ic":"wall","era":"H","t0":2000,"t1":100,"te":"The fortress that rebelled","ta":"القلعة التي تمرّدت","se":"A hill fort on Nabataean foundations that Queen Zenobia of Palmyra could not take","sa":"حصن على تلة بأسس نبطية عجزت الملكة زنوبيا التدمرية عن اقتحامه","desc":"A fortress on a hill about 620 m above sea level overlooking the oasis of Dumat al-Jandal, 50 km from Sakaka. Excavations in 1976 and by Khaleel al-Moaqil in 1986 found Nabataean and Roman pottery of the 1st–2nd centuries AD, placing its foundations in the Nabataean period. The medieval geographer Yaqut recorded the siege by Zenobia of Palmyra in the 3rd century AD, who could not take it. It has two storeys, stone below and mud brick above, four conical towers about 12 m high and two wells; it was damaged by cannon in 1853, besieged for ten months in 1909, and restored in 1995–2003 and again from 2018.","sig":"One of the few forts in Arabia with a documented history running from the Nabataeans to the 20th century.","ex":"Saudi Department of Antiquities (1976); K. I. al-Moaqil (1986); Saudi-Italian-French mission at Dumat al-Jandal; Saudi Commission for Tourism and National Heritage","disc":["Nabataean-Roman pottery of the 1st–2nd centuries AD","Besieged by Zenobia in the 3rd century"],"refs":["Wikipedia contributors (2026). Marid Castle, citing Saudipedia and Ministry of Culture (France), Archéologie: Dûmat al-Jandal.","Saudipedia (Ministry of Media, Saudi Arabia). Marid Castle."],"conf":"","ev":"","an":"","val":""},{"id":"rajajil-columns","n":"Columns of Rajajil","na":"أعمدة الرجاجيل","c":"archaeological","s":"Chalcolithic standing stones · Sakaka","lat":29.8125,"lng":40.22,"p":"Chalcolithic (Copper Age)","dr":"4th millennium BC","el":"54 groups of pillars up to 3 m tall","ic":"platform","era":"P","t0":6000,"t1":5000,"te":"The stone men of Al-Jawf","ta":"رجال الجوف الحجرية","se":"Fifty-four clusters of sandstone pillars raised 6,000 years ago, called \"the men\" because they look like a crowd from afar","sa":"أربع وخمسون مجموعة من أعمدة الحجر الرملي أُقيمت قبل 6,000 عام، سُمّيت «الرجال» لأنها تبدو كحشد من بعيد","desc":"Fifty-four groups of trimmed sandstone pillars, each group of 2 to 19 stones and the tallest about 3 m, in the Qara suburb south-east of Sakaka. Excavated by the Saudi General Administration of Antiquities and Museums in 1975–1976, which found scrapers, awls, blades and pottery confirming a Copper Age date of about 6,000 years ago; later finds include obsidian, sandstone vessels and beads, and two wells of the fifth millennium BC drawing water from 4–5 m down. Some pillars carry later Thamudic inscriptions. Aerial imagery suggests a rough alignment to sunrise and sunset, and the current view is a complex of small sanctuaries on the Wadi Sirhan corridor.","sig":"Among the oldest standing-stone monuments in Arabia, older than Stonehenge.","ex":"Saudi General Administration of Antiquities and Museums (1975–1976); Saudi Heritage Commission","disc":["54 groups, 2–19 pillars each","Fifth-millennium BC wells beside the stones"],"refs":["Wikipedia contributors (2026). Columns of Rajajil, citing Harrison, R. (2011), Enigmatic standing stele of Al-Rajajil, Arab News, and Saudipedia.","Saudipedia (Ministry of Media, Saudi Arabia). Columns of Rajajil."],"conf":"","ev":"","an":"","val":""},{"id":"al-ukhdood","n":"Al-Ukhdood (Najran)","na":"الأخدود (نجران)","c":"archaeological","s":"Walled caravan city of Najran · excavated since 1979","lat":17.4773,"lng":44.1793,"p":"Pre-Islamic South Arabian to early Islamic","dr":"c. 500 BC – AD 620s","el":"Granite inscription 2.3 m long","ic":"caravan","era":"H","t0":2500,"t1":1400,"te":"The city of the ditch","ta":"مدينة الأخدود","se":"A fortified town on the incense road, remembered for the massacre of its Christians in the 520s","sa":"بلدة محصّنة على طريق البخور، تُذكر بمذبحة مسيحييها في عشرينيات القرن السادس","desc":"The oldest part of Najran, south-east of the modern city near Bir Hima, occupied from at least 500 BC; its largest structure is a fort of stone and mud brick of the 1st century BC. A stop on the frankincense and myrrh route, briefly held by the Roman prefect Gallus around 25 BC. In the 520s the Himyarite king Dhu Nuwas massacred the town's Christians, events alluded to in the Quranic chapter al-Buruj, from which the name 'the ditch' comes; residents moved to present-day Najran in the 620s. Excavated by the Saudi Ministry of Culture since 1979 and with CNRS from 2016; finds announced in 2023 include three gold rings, a bronze bull's head, Attic pottery of the 3rd century BC and a granite inscription 48 cm high and 2.3 m long.","sig":"A place where South Arabian paganism, Christianity, Judaism and Islam all left traces within one walled town.","ex":"Saudi Ministry of Culture / Heritage Commission (1979 onwards); CNRS (2016 onwards)","disc":["Three gold rings with butterfly motifs (2023)","Attic pottery of the 3rd century BC"],"refs":["Wikipedia contributors (2026). Al-Okhdood, citing Saudipedia, Saudi Heritage Authority and Bowersock, G. W. (2013), The Throne of Adulis.","The National (21 Feb 2023). Rare pre-Islamic artefacts discovered in southern Saudi Arabia."],"conf":"","ev":"","an":"","val":""},{"id":"al-natah-khaybar","n":"Al-Natah, Khaybar","na":"النطاة، خيبر","c":"archaeological","s":"Bronze Age walled oasis town · found 2024","lat":25.69,"lng":39.28,"p":"Early to Late Bronze Age","dr":"c. 2400 – 1500 BC","el":"2.6 ha town for about 500 people","ic":"wall","era":"P","t0":4400,"t1":3400,"te":"A town hidden in the lava","ta":"بلدة مخبّأة في الحَرّة","se":"A 4,000-year-old town of 500 people inside a rampart-ringed oasis, found in 2024","sa":"بلدة عمرها 4,000 عام سكنها 500 شخص داخل واحة محاطة بسور، اكتُشفت عام 2024","desc":"A Bronze Age town of about 2.6 hectares in the Khaybar oasis, built around 2400–2000 BC and occupied until about 1500–1300 BC, with residential and funerary areas inside the fortifications and burials in stepped tower tombs. About 500 people lived there, grinding food, making and trading pottery, working metal, growing cereals and keeping animals. The find, published in PLOS ONE in 2024 by Guillaume Charloux's Khaybar Longue Durée project (CNRS with the Royal Commission for AlUla and AFALULA), suggests settled town life began in the oasis in the second half of the third millennium BC, when the region was thought to be purely pastoral.","sig":"The first Bronze Age town found in north-west Arabia, pushing back the start of urban life there by a thousand years.","ex":"Khaybar Longue Durée Archaeological Project (G. Charloux, CNRS; M. Almushawh, RCU), sponsored by the Royal Commission for AlUla and AFALULA","disc":["Published in PLOS ONE, 2024","Stepped tower tombs inside the ramparts"],"refs":["Charloux, G. et al. (2024). A Bronze Age town in the Khaybar walled oasis: debating early urbanization in Northwestern Arabia. PLOS ONE 19(10), e0309963.","Royal Commission for AlUla press release (Nov 2024). Archaeologists discover Bronze Age town buried in northwest Arabia.","Wikipedia contributors (2026). Al-Natah."],"conf":"","ev":"","an":"","val":""},{"id":"al-rabadha","n":"Al-Rabadha","na":"الربذة","c":"archaeological","s":"Abbasid pilgrim station on Darb Zubaydah · King Saud University excavations","lat":24.63,"lng":41.3,"p":"Early Islamic (Rashidun to Abbasid)","dr":"7th – 9th century AD","el":"Palace of 13 rooms around a courtyard","ic":"caravan","era":"H","t0":1400,"t1":1100,"te":"A station on the road to Mecca","ta":"محطة على درب الحج","se":"A pasture reserve of the early caliphs that grew into an Abbasid town on the Kufa–Mecca pilgrim road","sa":"حِمى من عهد الخلفاء الراشدين نما ليصبح بلدة عباسية على درب الحج بين الكوفة ومكة","desc":"A settlement about 200 km north-east of Medina that began as a pasture reserve (hima) under the first caliphs, grew into a town in the Umayyad period and peaked in the early Abbasid era of the 3rd century AH (9th century AD) as a major station on Darb Zubaydah, the pilgrim road from Kufa to Mecca. The companion Abu Dharr al-Ghifari spent his last years and died here. Excavations by King Saud University revealed fortified residential quarters, palaces, two mosques, an industrial area with a glass furnace, a circular reservoir and many domestic water tanks; the main palace has 13 rooms opening onto a central courtyard, and houses were of sun-dried mud brick on stone foundations. Finds include pottery, coins, inscriptions and jewellery.","sig":"One of the best-excavated early Islamic towns in Arabia and a key to the archaeology of the pilgrim roads.","ex":"King Saud University, Department of Archaeology (S. al-Rashid)","disc":["Glass-making furnace and two mosques","Peak in the 9th century AD"],"refs":["Al-Rashid, S. (1986). Al-Rabadhah: Portrait of Early Islamic Civilisation in Saudi Arabia. King Saud University, Riyadh.","King Saud University Museum. Al-Rabadha (site description).","Wikipedia contributors (2026). Al-Rabadha, citing Shaw, I. & Jameson, R., A Dictionary of Archaeology."],"conf":"","ev":"","an":"","val":""},{"id":"thee-ain-village","n":"Thee Ain (Dhee Ayn) Marble Village","na":"قرية ذي عين الأثرية","c":"archaeological","s":"Stone village on a white marble hill · Al-Baha","lat":19.7674,"lng":41.4342,"p":"Islamic (Ottoman era)","dr":"10th century AH / 16th century AD – present","el":"49 stone houses of up to four storeys","ic":"wall","era":"H","t0":450,"t1":0,"te":"A village on a white hill","ta":"قرية فوق تلّ أبيض","se":"Forty-nine stone houses stacked on a marble outcrop above a spring-fed valley","sa":"تسع وأربعون بيتاً حجرياً تتراصّ فوق نتوء رخامي يعلو وادياً تغذيه عين ماء","desc":"A village in the Al-Mikhwah district of Al-Baha, about 20 km south-west of Al-Makhwah, established in the 10th century AH (16th century AD) and named after the water that flows from the mountains beside it. It has 49 houses, 9 of one storey, 19 of two, 11 of three and 10 of four, with a mosque by the stream; a historical source reports high-quality marble in the area. The Saudi Tourism Authority allocated 16 million riyals to a three-phase, five-year rehabilitation that reopened the mosque and turned buildings into a museum and visitor centre. It is on UNESCO's tentative list as 'Zee Ain Heritage Village in Al-Baha Region'.","sig":"The most striking example of the stone-tower villages of the Sarawat, set on a hill of white rock.","ex":"Saudi Tourism Authority / Ministry of Culture rehabilitation project","disc":["Houses of one to four storeys on a marble outcrop","On the UNESCO tentative list"],"refs":["Wikipedia contributors (2026). Thee Ain, citing UNESCO tentative list entry and Al-Sughair, S. (2015), Arab News.","UNESCO World Heritage Centre. Zee Ain Heritage Village in Al-Baha Region (tentative list)."],"conf":"","ev":"","an":"","val":""},{"id":"rijal-almaa","n":"Rijal Almaa","na":"رجال ألمع","c":"archaeological","s":"Stone-tower village of Asir · UNESCO tentative list","lat":18.2125,"lng":42.2736,"p":"Islamic (medieval to 20th century)","dr":"12th century AD – present","el":"About 60 palaces of up to eight floors","ic":"wall","era":"H","t0":900,"t1":0,"te":"Towers of stone and colour","ta":"أبراج من حجر ولون","se":"Sixty stone, clay and wood palaces, their rooms painted in Al-Qatt patterns, on the old road from Yemen","sa":"ستون قصراً من الحجر والطين والخشب، زُيّنت غرفها بنقوش القطّ، على الطريق القديم من اليمن","desc":"A village about 45–50 km west of Abha with around 60 multi-storey buildings of natural stone, clay and wood, some reaching eight floors, with coloured wooden windows and interior walls painted in the Al-Qatt style. Mentioned as a civic centre in 550 AH (1155 AD) and as capital of the Hilli emirate in 730 AH (1329 AD), it linked Yemen and the Levant through Mecca and Medina. Al Al-wan Palace, more than four centuries old, houses a heritage museum opened in 1987 with over 2,000 objects. Rehabilitated from 2015 with the private sector, awarded the Prince Sultan bin Salman Prize for Urban Heritage in 2017, and submitted to UNESCO's tentative list on 8 April 2015 under criteria (iv) and (v).","sig":"The finest surviving ensemble of Asir's stone-tower architecture and painted interiors.","ex":"Saudi Commission for Tourism and National Heritage; Rijal Almaa Heritage Museum","disc":["Al-Qatt painted interiors","Tentative list since 2015"],"refs":["UNESCO World Heritage Centre. Rijal Almaa Heritage Village in Assir Region (tentative list, submitted 8 April 2015).","Wikipedia contributors (2026). Rijal Almaa, citing Reuters (2016) and Arab News (2018, 2023)."],"conf":"","ev":"","an":"","val":""},{"id":"shuwayhitiyah","n":"Ash-Shuwayhitiyah Palaeolithic Site","na":"موقع الشويحطية الأثري","c":"archaeological","s":"Oldest stone-tool site in Saudi Arabia · Al-Jawf","lat":30.25,"lng":39.87,"p":"Lower Palaeolithic (Developed Oldowan)","dr":"More than 1 million years ago","el":"1,517 quartzite tools in 16 concentrations","ic":"trench","era":"P","t0":1300000,"t1":1000000,"te":"The first toolmakers of Arabia","ta":"أوائل صانعي الأدوات في الجزيرة","se":"Choppers and spheroids of quartzite left by early humans over a million years ago","sa":"فؤوس وأحجار كروية من الكوارتزيت تركها إنسان قديم قبل أكثر من مليون عام","desc":"A broad canyon about 45 km north-west of Sakaka where a joint American-Saudi team recorded, in 1985, a horseshoe-shaped site almost 5 km long with 16 artefact concentrations spaced 200–350 m apart. It yielded 1,517 quartzite choppers, polyhedrons, spheroids and discoids of the Developed Oldowan tradition first defined at Olduvai Gorge, dated to more than one million years ago, the oldest found in Saudi Arabia. The site had been discovered in 1977 under the Comprehensive Archaeological Survey Program; Saudipedia records 17 settlements and 1,884 tools in all, some linked to about 1.3 million years ago, and later rock art of camels and ibex on a nearby hill.","sig":"The earliest evidence of human presence in Saudi Arabia.","ex":"Comprehensive Archaeological Survey Program (1977); American-Saudi survey (N. Whalen, 1985); Heritage Commission survey (2018)","disc":["Developed Oldowan choppers and spheroids","Site almost 5 km long"],"refs":["Whalen, N. M. & Pease, D. W. (1992). Early Mankind in Arabia. Aramco World 43(4).","Saudipedia (Ministry of Media, Saudi Arabia). Ash-Shuwayhitiyah Archaeological Site."],"conf":"","ev":"","an":"","val":""},{"id":"harrat-khaybar-white-volcanoes","n":"White Volcanoes of Harrat Khaybar","na":"براكين خيبر البيضاء","c":"geological","s":"Jabal Abyad, Jabal Bayda and Jabal Qidr · active lava field","lat":25.6,"lng":39.9,"p":"Quaternary volcanism","dr":"Last 5 million years; last eruption 7th century AD","el":"Jabal Bayda crater 1,400 m across","ic":"flame","era":"D","t0":5000000,"t1":1350,"te":"Black and white volcanoes","ta":"براكين سوداء وبيضاء","se":"A pale rhyolite dome and tuff cone beside a black stratovolcano, in a 14,000 km² lava field","sa":"قبة ريوليتية شاحبة ومخروط رمادي إلى جوار بركان أسود، في حقل حمم مساحته 14,000 كم²","desc":"Harrat Khaybar covers about 14,000 km² of western Saudi Arabia, built by eruptions over the past 5 million years along a 100 km north-south vent system; eight lava flows are younger than 1,500 years and the last reported eruption was in the 7th century. At its heart stand three young vents: Jabal Qidr, a basaltic stratovolcano with a 400 m summit crater and the only stratovolcano in the western harrats; Jabal Abyad, a dome of thick silica-rich rhyolitic lava rising above 2,090 m, the highest point of the harrats; and Jabal Bayda, a tuff cone with a crater about 1,400 m wide formed when magma met groundwater. The white colour comes from ash of comenditic lavas; 'abyad' and 'bayda' both mean white.","sig":"The clearest place in Arabia to see black basalt and white silica-rich volcanoes side by side.","ex":"NASA Earth Observatory (Landsat 9, 2024); Saudi Geological Survey","disc":["Eight lava flows under 1,500 years old","Only stratovolcano in the western harrats"],"refs":["NASA Earth Observatory (22 May 2024). White and Black Volcanoes of Saudi Arabia.","Smithsonian Institution Global Volcanism Program. Harrat Khaybar."],"conf":"","ev":"","an":"","val":""},{"id":"harrat-lunayyir-2009","n":"Harrat Lunayyir 2009 Dyke Intrusion","na":"حرة لونير وزلازل 2009","c":"geological","s":"Earthquake swarm and surface rupture · Nature Geoscience 2010","lat":25.17,"lng":37.75,"p":"Red Sea rifting, Neogene to present","dr":"Lava field of the last 30 million years; crisis April – June 2009","el":"8 km rupture with 91 cm offset","ic":"quake","era":"D","t0":30000000,"t1":17,"te":"The ground that split in 2009","ta":"الأرض التي انشقّت عام 2009","se":"More than 30,000 earthquakes and a 10 km dyke that nearly reached the surface forced 30,000 people from their homes","sa":"أكثر من 30,000 زلزال وقاطع صخري بطول 10 كم كاد يبلغ السطح أجبر 30,000 شخص على مغادرة منازلهم","desc":"A lava field in north-west Saudi Arabia, one of the harrats formed along the Red Sea over the past 30 million years. From April to June 2009 a swarm of more than 30,000 earthquakes, six of them magnitude 4.6 to 5.7 at the peak of 17–20 May, accompanied the intrusion of a near-vertical north-west-trending dyke about 10 km long that almost reached the surface. Radar interferometry showed over 1 m of east-west extension across a 40 km × 40 km area and more than 40 cm of uplift, with an 8 km surface rupture of 91 cm offset. Saudi civil protection evacuated more than 30,000 people. The Nature Geoscience study concluded that rift margins stay active sites of extension, not only the central Red Sea axis.","sig":"The best-recorded magma intrusion in Arabia, proving the Red Sea margin is still pulling apart.","ex":"Saudi Geological Survey; US Geological Survey (J. Pallister et al.); KAUST (S. Jónsson)","disc":["Six quakes of M4.6–5.7 in four days","Dyke 10 km long, extension over 1 m"],"refs":["Pallister, J. S. et al. (2010). Broad accommodation of rift-related extension recorded by dyke intrusion in Saudi Arabia. Nature Geoscience 3, 705–712.","Jónsson, S. (2011). The 2009 earthquake crisis and dike intrusion in western Saudi Arabia. Earthquake Research Institute, University of Tokyo seminar."],"conf":"","ev":"","an":"","val":""},{"id":"jabal-al-qarah-caves","n":"Jabal Al-Qarah Caves","na":"كهوف جبل القارة","c":"geological","s":"Joint-controlled canyons in the Hofuf Formation · Al-Ahsa","lat":25.41,"lng":49.67,"p":"Upper Miocene – Lower Pliocene (Hofuf Formation)","dr":"c. 11 – 3.6 million years ago","el":"Boxwork of linear passages, cool all year","ic":"cliff","era":"D","t0":11000000,"t1":3600000,"te":"A mountain of cool corridors","ta":"جبل الممرات الباردة","se":"Deep fissures in soft sandstone and marl widened into tall passages that stay cool in summer","sa":"شقوق عميقة في حجر رملي ومارل لين اتسعت إلى ممرات عالية تبقى باردة في الصيف","desc":"An outlier mesa about 13 km east of Hofuf at the eastern edge of the Shedgum Plateau, cut into calcareous sandstone, marl and clay of the Upper Miocene to Lower Pliocene Hofuf Formation. A 2006 study in the Journal of Cave and Karst Studies found that its tall, linear passages and narrow canyons formed by erosional enlargement of very deep, narrow joint-controlled fissures, the best-developed boxwork of its kind in the Eastern Province. The caves stay much cooler than the air outside with an almost constant temperature, and were used to store grain and shelter travellers. The mountain is part of the Al-Ahsa Oasis cultural landscape inscribed by UNESCO in 2018.","sig":"A rare example of caves made by joints and weathering rather than by dissolving limestone.","ex":"King Fahd University of Petroleum and Minerals (M. Hussain, F. Al-Khalifah); Al-Ahsa Municipality","disc":["Joint-controlled fissures, not karst","Part of the 2018 World Heritage oasis"],"refs":["Hussain, M., Al-Khalifah, F. & Khandaker, N. I. (2006). The Jabal Al Qarah caves of the Hofuf area, northeastern Saudi Arabia: a geological investigation. Journal of Cave and Karst Studies 68(1), 12–21.","Arab News (2025). A story of stone: how Jabal Al-Qarah shapes the soul of Hofuf."],"conf":"","ev":"","an":"","val":""},{"id":"ain-heet-cave","n":"Ain Heet Cave","na":"كهف عين هيت","c":"geological","s":"Anhydrite sinkhole with an underground lake · Al-Kharj","lat":24.4861,"lng":46.9972,"p":"Limestone and anhydrite karst","dr":"Surveyed 1938; lake 120 m below the surface","el":"Entrance 74 m wide, cave 180–200 m deep","ic":"sinkhole","era":"D","t0":150000000,"t1":0,"te":"A lake under the desert","ta":"بحيرة تحت الصحراء","se":"A collapse cave where the first anhydrite in the kingdom was identified and a cold lake lies 120 m down","sa":"كهف انهياري تعرّف فيه الجيولوجيون على أول أنهيدريت في المملكة، وتقبع فيه بحيرة باردة على عمق 120 م","desc":"A solutional cave about 30–40 km south-east of Riyadh near Al-Kharj, in a hill of limestone and anhydrite. Its entrance is about 74 m wide and the cave descends 180–200 m on a widening slope to an underground lake about 120 m below the surface, an opening into a vast groundwater reservoir whose water was once drawn by caravans. Geologists came at the invitation of King Abdulaziz for the first surface exploration of anhydrite rock in Saudi Arabia, in 1938 according to Wikipedia; Swedish divers later tracked its water-filled passages. It is one of 1,826 caves recorded across the kingdom and is listed by the Quality of Life programme among the top fourteen landmarks of Riyadh Province, though rockfalls make the descent dangerous.","sig":"The most accessible window into the great aquifer beneath central Arabia.","ex":"Saudi Geological Survey; Quality of Life Program (Vision 2030)","disc":["First anhydrite identified in Saudi Arabia","Underground lake 120 m down"],"refs":["Saudipedia (Ministry of Media, Saudi Arabia). Ain Heet Cave.","Wikipedia contributors (2026). Ein Heet Cave."],"conf":"","ev":"","an":"","val":""},{"id":"ghawar-field","n":"Ghawar Oil Field (Ain Dar discovery)","na":"حقل الغوار (اكتشاف عين دار)","c":"geological","s":"Largest conventional oil field on Earth · discovered 1948","lat":25.95,"lng":49.28,"p":"Upper Jurassic Arab-D reservoir","dr":"Reservoir c. 150 million years old; produced since 1951","el":"280 km long, about 30 km wide","ic":"oil","era":"D","t0":150000000,"t1":78,"te":"The king of giant fields","ta":"ملك الحقول العملاقة","se":"An anticline 280 km long whose Jurassic carbonates have yielded more than 60 billion barrels","sa":"طيّة محدّبة بطول 280 كم أنتجت كربوناتها الجوراسية أكثر من 60 مليار برميل","desc":"Discovered in 1948 with the Ain Dar test well about 200 km east of Riyadh, the first post-war find in the country, followed by Haradh (1949), Uthmaniyah (1951), Shedgum (1952) and Hawiyah (1953). The field follows the En Nala anticline, trending N15°E on a basement horst, about 280 km long and 30 km wide with a productive area of about 2,800 km². The main reservoir is the Upper Jurassic Arab-D carbonate, with an oil column of 396 m, average porosity about 15% and oil of 30–34° API, sealed by 30–100 m of anhydrite and sourced from the Hanifa and Tuwaiq formations. Production began in 1951 at 126,000 barrels a day, peaked at 5.7 million in 1981, and cumulative output reached 66 billion barrels by 2007.","sig":"No other single structure has supplied so much of the world's oil.","ex":"Aramco (Saudi Aramco) exploration and production","disc":["Ain Dar well struck oil in 1948","Peak 5.7 million barrels a day in 1981"],"refs":["GEO ExPro. The King of Giant Fields (Ghawar, Saudi Arabia).","Afifi, A. M. (2004). Ghawar: the anatomy of the world's largest oil field. AAPG Search and Discovery."],"conf":"","ev":"","an":"","val":""},{"id":"jabal-al-lawz","n":"Jabal al-Lawz","na":"جبل اللوز","c":"geological","s":"Granite peak of the Midian mountains · snow most winters","lat":28.654,"lng":35.304,"p":"Arabian Shield granite","dr":"Rock art said to be c. 10,000 BC; snow every winter","el":"2,549 – 2,580 m high","ic":"cliff","era":"D","t0":600000000,"t1":0,"te":"The almond mountain of snow","ta":"جبل اللوز حيث يسقط الثلج","se":"A light granite peak above the Gulf of Aqaba, highest in Midian, dusted with snow almost every winter","sa":"قمة من الغرانيت الفاتح تعلو خليج العقبة، الأعلى في جبال مدين، يكسوها الثلج كل شتاء تقريباً","desc":"The highest peak of the Midian mountains in Tabuk Province, about 200 km north-west of Tabuk and north-east of Al-Bad', rising to 2,549 m (Saudipedia) or 2,556–2,580 m (Wikipedia) with a prominence of about 1,600 m. The peak is a light-coloured calc-alkaline granite cut by east-trending rhyolite and andesite dykes, mapped by Brown, Johnson and Trent for the Directorate General of Mineral Resources in 1967, and is surrounded mostly by sandy terrain; valleys drain to Wadi Afal, Wadi Reem and Wadi al-Abyad. It receives snow almost every winter, has rock drawings, ancient inscriptions and Islamic writings, and is named after its almond trees. The range lies within the NEOM area.","sig":"One of the few places in Arabia where snow falls regularly, on some of the peninsula's oldest rock.","ex":"Directorate General of Mineral Resources geological mapping (1967); Saudi Geological Survey","disc":["Granite with rhyolite and andesite dykes","Snow nearly every winter"],"refs":["Saudipedia (Ministry of Media, Saudi Arabia). Jabal al-Lawz.","Wikipedia contributors (2026). Jabal al-Lawz, citing Brown, G. F., Johnson, R. F. & Trent, V. A. (1967), Geologic map of the Jabal al Lawz quadrangle, DGMR."],"conf":"","ev":"","an":"","val":""},{"id":"elephant-rock-alula","n":"Elephant Rock (Jabal AlFil)","na":"جبل الفيل","c":"geological","s":"Wind-carved sandstone monolith · AlUla","lat":26.6892,"lng":37.9816,"p":"Cambrian – Ordovician sandstone","dr":"Rock 540 – 485 million years old; uplifted 30 million years ago","el":"52 m high","ic":"cliff","era":"D","t0":540000000,"t1":30000000,"te":"An elephant made of sand","ta":"فيل من الحجر الرملي","se":"A 52 m sandstone outcrop sculpted by rain, wind and sand into the shape of an elephant","sa":"نتوء من الحجر الرملي بارتفاع 52 م نحتته الأمطار والرياح والرمال على هيئة فيل","desc":"A sandstone monolith 52 m high at AlUla in north-west Saudi Arabia, eroded by rain, wind and blown sand over millions of years into the form of an elephant with its trunk touching the ground. The AlUla sandstones were laid down about 540–485 million years ago and uplifted about 30 million years ago when the Red Sea began to open, according to the Royal Commission for AlUla's geology notes. It is the best-known of the sandstone outcrops of the AlUla valley and a centre of night-sky tourism since the region's dark-sky park opened in 2024.","sig":"The most photographed rock in Saudi Arabia and a textbook example of differential erosion.","ex":"Royal Commission for AlUla","disc":["Sandstone 540–485 million years old","Uplift when the Red Sea opened"],"refs":["Wikipedia contributors (2026). Elephant Rock (Saudi Arabia), citing BBC Travel (2024) and Royal Commission for AlUla, Geology of AlUla.","Royal Commission for AlUla. AlUla Geology Booklet."],"conf":"","ev":"","an":"","val":""},{"id":"wadi-al-disah","n":"Wadi Al Disah","na":"وادي الديسة","c":"geological","s":"Sandstone canyon with year-round springs · Tabuk","lat":27.6311,"lng":36.5494,"p":"Sandstone canyon","dr":"Canyon of about 18 km; tentative list since 2023","el":"Cliffs up to 500 m","ic":"river","era":"D","t0":500000000,"t1":0,"te":"The valley of palms","ta":"وادي النخيل","se":"Red sandstone columns and cliffs up to 500 m frame a stream that flows all year through palms and oleander","sa":"أعمدة وجروف من الحجر الرملي الأحمر يصل ارتفاعها إلى 500 م تحيط بجدول يجري طوال العام بين النخيل والدفلى","desc":"A valley in south-west Tabuk Province, about 220 km from Tabuk, running about 125 km from north-east to south-west towards the Red Sea, with a linear canyon section of about 18 km through red sandstone columns and cliffs up to 500 m high shaped by water and wind. Freshwater springs flow all year, supporting palms, citrus, jujube, mint, papyrus, oleander and sedge. The canyon holds Nabataean rock-cut tomb facades and early Arabic inscriptions, and lies north-west of the Prince Mohammed bin Salman Nature Reserve. A 2025 Geoheritage study rated it a geomorphosite of high scientific value, and it has been on UNESCO's tentative list since 2023 as part of the 'Bioclimatic Refugia of Western Arabia'.","sig":"A living canyon where water, rock and Nabataean history meet in one of the driest regions on Earth.","ex":"KFUPM geoheritage study (S. Sen, F. S. Al-Ismail et al., 2025); Public Investment Fund tourism project","disc":["Springs that flow all year","Nabataean tombs cut into the canyon walls"],"refs":["Sen, S. et al. (2025). Geomorphosite assessment of Wadi Al Disha: from the perspective of geotourism development in a canyon. Geoheritage 17(4), 135.","Wikipedia contributors (2026). Wadi Al Disah, citing UNESCO, Bioclimatic Refugia of Western Arabia (tentative list) and Arab News."],"conf":"","ev":"","an":"","val":""},{"id":"ain-al-harrah-lith","n":"Ain Al-Harrah Hot Spring, Al-Lith","na":"عين الحارّة، الليث","c":"geological","s":"Hottest spring of the Red Sea coast · geothermal field","lat":20.45,"lng":40.45,"p":"Red Sea rift geothermal system","dr":"Rift heat of the last 30 million years; studied 2024","el":"Water at 56 – 81 °C","ic":"steam","era":"D","t0":30000000,"t1":0,"te":"Rain that comes back boiling","ta":"مطر يعود غالياً","se":"Rainwater that sinks along rift fractures and returns at up to 81 °C from a reservoir of 150–205 °C","sa":"مياه أمطار تغور عبر صدوع الأخدود وتعود بحرارة تصل إلى 81 درجة من خزان حرارته 150–205 درجات","desc":"The hottest of four hot springs in the Al-Lith area of western Saudi Arabia, discharging water at 56–81 °C. A 2024 study in ACS Omega found the water to be of meteoric origin (rainwater), moderately alkaline sodium-bicarbonate type with 1,830–2,055 mg/L dissolved solids, and estimated a reservoir temperature of 150–205 °C from Na-K-Ca, K/Mg and quartz geothermometers, a medium-to-high-enthalpy system linked to Red Sea rifting. Magnetotelluric soundings published in 2024 imaged a fracture zone carrying fluids to the surface and a conductive body below 3.5 km interpreted as the heat source. The spring is also a local bathing destination.","sig":"Saudi Arabia's best-studied geothermal prospect, where the Red Sea rift heats the ground within reach of a drill.","ex":"King Fahd University of Petroleum and Minerals (P. Soupios, J. Rafiq, A. L. Ashadi); University of Cologne","disc":["Reservoir estimated at 150–205 °C","Heat source below 3.5 km"],"refs":["Rafiq, J. et al. (2024). Hydrochemical characterization, geothermometry and origin of Ain Al-Harrah hot spring, Al-Lith, Saudi Arabia. ACS Omega 9(23), 24807–24818.","Ashadi, A. L. et al. (2024). Magnetotelluric case study from Ain Al-Harrah hot spring, Al-Lith, Saudi Arabia. Arabian Journal for Science and Engineering 49(1), 899–912."],"conf":"","ev":"","an":"","val":""},{"id":"mahazat-as-sayd","n":"Mahazat as-Sayd Protected Area","na":"محمية محازة الصيد","c":"ecology","s":"Fenced reintroduction reserve for oryx and ostrich · since 1988","lat":22.25,"lng":41.8,"p":"Protected since 1988","dr":"1988 – present","el":"220 km of fence around 2,244 km²","ic":"gazelle","era":"N","t0":38,"t1":0,"te":"A fence around a second chance","ta":"سياج حول فرصة ثانية","se":"The largest fenced reserve in the kingdom, built to bring back the Arabian oryx, sand gazelle, houbara and ostrich","sa":"أكبر محمية مسيّجة في المملكة، أُنشئت لإعادة المها العربي وغزال الريم والحبارى والنعام","desc":"A reserve of 2,244 km² on the arid plains 170 km north-east of Taif, protected since 1988 and fully enclosed by about 220 km of 2.1 m chain-link fence completed by March 1989. It was set aside mainly as a reintroduction site for the Arabian oryx, Arabian sand (reem) gazelle, Macqueen's bustard (houbara) and the North African red-necked ostrich, released from captive breeding. Wikipedia gives the area as 220,000 ha. It is listed by BirdLife as an Important Bird Area and managed by the National Center for Wildlife (formerly the Saudi Wildlife Authority).","sig":"The site where the Arabian oryx first returned to the wild in Saudi Arabia.","ex":"National Center for Wildlife (formerly NCWCD / Saudi Wildlife Authority); King Khalid Wildlife Research Centre breeding programme","disc":["Fenced 2,244 km² reserve","Oryx, gazelle, houbara and ostrich reintroduced"],"refs":["Wikipedia contributors (2026). Mahazat as-Sayd Protected Area.","Birds of Saudi Arabia (2020). Mahazat as-Sayd Protected Area.","BirdLife International / Key Biodiversity Areas. Mahazat as-Sayd (site 8271)."],"conf":"","ev":"","an":"","val":""},{"id":"ibex-reserve","n":"Ibex Reserve (Hawtat Bani Tamim)","na":"محمية الوعول (حوطة بني تميم)","c":"ecology","s":"Nubian ibex canyons of the Tuwaiq escarpment · since 1988","lat":23.4,"lng":46.45,"p":"Protected since 1988","dr":"1988 – present","el":"1,841 km² of plateau and canyon","ic":"gazelle","era":"N","t0":38,"t1":0,"te":"Lords of the sandstone canyons","ta":"سادة الأودية الصخرية","se":"A rugged plateau of the Tuwaiq range where ibex recovered from a few dozen to more than 300","sa":"هضبة وعرة في جبال طويق تعافت فيها الوعول من بضع عشرات إلى أكثر من 300","desc":"A reserve of 1,840.9 km² about 180 km south of Riyadh, between Al-Hariq and Hawtat Bani Tamim, covering a rugged plateau of the Tuwaiq mountain range cut by wadis and ravines, with western edges reaching 1,097 m. Declared a special ibex reserve in 1988 by the National Commission for Wildlife Conservation and Development after local villagers had informally kept grazing out of the central canyons; a 1995 Aramco World account by Khushal Habibi reported ibex rising from a few dozen to more than 300 after the hunting ban. Arabian gazelles were relocated here in 1990 and thrived. Acacia, Ziziphus and Haloxylon grow in the valleys.","sig":"The place where the Nubian ibex was pulled back from the edge in central Arabia.","ex":"National Commission for Wildlife Conservation and Development (1988); National Center for Wildlife supervisory council (2024)","disc":["Ibex up from a few dozen to more than 300","Arabian gazelles released 1990"],"refs":["Habibi, K. (1995). Lords of the Sandstone Canyons. Aramco World 46(5).","Saudipedia (Ministry of Media, Saudi Arabia). The Ibex Reserve."],"conf":"","ev":"","an":"","val":""},{"id":"umm-al-qamari-islands","n":"Umm al-Qamari Islands","na":"جزر أم القماري","c":"ecology","s":"Seabird and dove islands · first protected area in the kingdom","lat":19.07,"lng":41.08,"p":"Protected since 1977","dr":"1977 – present","el":"Two islands, 4.03 km²","ic":"bird","era":"N","t0":49,"t1":0,"te":"Islands of the doves","ta":"جزر القماري","se":"Two coral islets off Al-Qunfudhah where doves, egrets, pelicans and ospreys breed over living reefs","sa":"جزيرتان مرجانيتان قبالة القنفذة يتكاثر فيها القماري والبلشون والبجع والعقاب النسّاري فوق شعاب حيّة","desc":"Two small islands, Umm al-Qamari al-Braniah and al-Fuqaniah, south-west of Al-Qunfudhah on the Red Sea coast, with a reported area of 4.03 km² in the World Database on Protected Areas. Listed as a protected area in 1977, they are described as the first protected area in Saudi Arabia (Saudipedia gives 1988 for the reserve's formal establishment). They are named after the turtle doves that gather on them in migration, and host collared doves, herons and egrets, pelicans, gulls and osprey; the reefs around the outer island are diverse and mostly living, and the vegetation includes Salvadora persica and Suaeda. Managed by the National Center for Wildlife.","sig":"The oldest protected area in Saudi Arabia and a key Red Sea seabird colony.","ex":"National Center for Wildlife (formerly Saudi Wildlife Authority)","disc":["Protected since 1977","Breeding doves, egrets, pelicans and osprey"],"refs":["Wikipedia contributors (2026). Umm al-Qamari Islands, citing Protected Planet and IUCN/WCMC (1991), Protected Areas of the World.","Saudipedia (Ministry of Media, Saudi Arabia). Umm al-Qamari Islands Reserve.","Protected Planet (UNEP-WCMC). Umm al-Qamari Islands (WDPA 555624837)."],"conf":"","ev":"","an":"","val":""},{"id":"harrat-al-harrah","n":"Harrat al-Harrah Protected Area","na":"محمية حرة الحرة","c":"ecology","s":"Basalt plateau of wolves, hyenas and houbara · since 1987","lat":31.2,"lng":38.4,"p":"Protected since 1987","dr":"1987 – present","el":"About 13,775 km² of black basalt","ic":"gazelle","era":"N","t0":39,"t1":0,"te":"Life on the black stones","ta":"حياة فوق الحجارة السوداء","se":"A huge lava plateau in the far north where 22 mammal species, including wolf, hyena and caracal, were recorded","sa":"هضبة بركانية شاسعة في أقصى الشمال سُجّل فيها 22 نوعاً من الثدييات، منها الذئب والضبع والوشق","desc":"A volcanic plateau of black basalt in the far north of Saudi Arabia, with low volcanic hills between 800 and 1,150 m, covering about 13,775 km² (12,150 km² in the 1997 survey); one of the first reserves created by the Saudi wildlife authority, in 1987 (1986 in the survey). Surveys from 1991 to 1996 by Seddon, Van Heezik and Nader confirmed 22 mammal species including eight native carnivores, among them the Arabian wolf, striped hyena and caracal, as well as goitered gazelle, red fox, hare and jerboa. Birds include houbara bustard, golden eagle and nine species of lark, and the wadis carry Lycium, Tamarix and Calligonum.","sig":"The largest of the kingdom's early reserves and its best stronghold for large desert carnivores.","ex":"Saudi Wildlife Authority / NCWCD (1987); Seddon, Van Heezik & Nader mammal survey 1991–1996","disc":["22 mammal species, 8 native carnivores","Basalt hills 800–1,150 m high"],"refs":["Seddon, P. J., Van Heezik, Y. & Nader, I. A. (1997). Mammals of the Harrat al-Harrah Protected Area, Saudi Arabia. Zoology in the Middle East 14.","Wikipedia contributors (2026). Horah Al-Horah Reserve, citing Abuzinada, A. H. (2003), Journal of Arid Environments 54."],"conf":"","ev":"","an":"","val":""},{"id":"king-khalid-royal-reserve","n":"King Khalid Royal Reserve (Thumamah)","na":"محمية الملك خالد الملكية (الثمامة)","c":"ecology","s":"Former royal farm turned wildlife reserve · Riyadh","lat":25.3194,"lng":46.6861,"p":"Park since 1983, royal reserve since 2019","dr":"1983 – present","el":"About 720 km² with 148 bird species","ic":"gazelle","era":"N","t0":43,"t1":0,"te":"A farm that became a wilderness","ta":"مزرعة صارت برّية","se":"King Khalid's farm north-east of Riyadh, a public park from 1983 and a royal reserve since 2019 where oryx and gazelle are released","sa":"مزرعة الملك خالد شمال شرق الرياض، متنزه عام منذ 1983 ومحمية ملكية منذ 2019 يُطلق فيها المها والغزلان","desc":"A reserve of about 720 km² in the Thumamah area north-east of Riyadh, beside King Khalid International Airport and some 80 km from downtown. It began as King Khalid's private farm; after his death in 1982 it was nationalised, opened as al-Thumamah Wildlife Park on 2 August 1983, and renamed King Khalid Royal Reserve by royal decree in October 2019. Saudipedia records about 195 plant species, 13 mammals, 148 birds and 26 reptiles. On 21 March 2022 the National Center for Wildlife released 20 Arabian oryx and 30 Arabian sand gazelles here, and the King Khalid Wildlife Research Center within the reserve breeds animals for release.","sig":"The wildlife reserve closest to the capital and the home of its captive-breeding centre.","ex":"Council of Royal Reserves; National Center for Wildlife; King Khalid Wildlife Research Center","disc":["20 oryx and 30 sand gazelles released 2022","148 bird species recorded"],"refs":["Saudipedia (Ministry of Media, Saudi Arabia). King Khalid Royal Reserve.","Wikipedia contributors (2026). King Khalid Royal Reserve, citing Royal Commission for Riyadh City and SPA (2019)."],"conf":"","ev":"","an":"","val":""},{"id":"musayqira","n":"Musayqira (Graffiti Rock)","na":"المسيقرة (صخرة الكتابات)","c":"archaeological","ic":"eye","era":"H","s":"Rock art and inscriptions on a sandstone hill","lat":24.3162,"lng":45.6399,"p":"Undated · many phases","dr":"Thamudic to Arabic, Latin and Chinese graffiti","el":"Two panels, 18 m and 21 m above the hill base","t0":2800,"t1":100,"te":"The hill that kept every visitor’s name","ta":"التلّ الذي حفظ أسماء زوّاره","se":"Ibex, lions, ostriches and camels share a lone sandstone hill with writing in four scripts","sa":"وعول وأسود ونعام وجمال تتقاسم تلًّا رمليًا منفردًا مع كتابات بأربعة خطوط","desc":"An isolated sandstone inselberg in Al-Quwaiyah Governorate with two rock-art panels on opposite sides, about 18 m (west) and 21 m (east) above the base. Engravings show humans, ibex, asses, ostriches, lions, cattle, camels, horses and dogs, with Thamudic, Arabic, Latin and Chinese graffiti. Andreae and colleagues studied the iconography and measured the rock varnish with portable X-ray fluorescence.","sig":"Many phases of people marking the same landscape, from ancient rock art to modern travellers’ names.","ex":"Andreae et al. (2021)","disc":["Four scripts on one hill","Rock varnish measured by portable XRF"],"refs":["Andreae, M.O., Al-Amri, A., Al-Jibrin, F.H. & Alsharekh, A.M. (2021). Iconographic and archaeometric studies on the rock art at Musayqira, Al-Quwaiyah Governorate, central Saudi Arabia. Arabian Archaeology and Epigraphy 32(S1), 153–182. https://doi.org/10.1111/aae.12191"],"conf":"Undated in the source; the timeline position is an estimate from the scripts present","ev":"","an":"","val":""},{"id":"jabal-umm-sariha","n":"Jabal Umm Sariha","na":"جبل أم سريحة","c":"archaeological","ic":"eye","era":"H","s":"Rock art and Thamudic inscriptions in a wadi","lat":24.0275,"lng":45.2363,"p":"Undated","dr":"Thamudic inscriptions","el":"Engravings up to about 10 m above the wadi bed","t0":2800,"t1":1400,"te":"Camels in a hidden ravine","ta":"جمال في وادٍ خفي","se":"A small ravine near Al-Quwaiyah where camels and human figures climb the rock beside old Thamudic writing","sa":"شعب صغير قرب القويعية تصعد فيه الجمال والأشكال البشرية الصخر بجوار كتابات ثمودية قديمة","desc":"A rock-art locality in a small wadi on the southern flank of Jabal Umm Sariha, about 2.5 km south-west of Al-Quwaiyah and 51 km south-west of Musayqira. Engravings run from the wadi bed to about 10 m up a ravine side and are dominated by camels and human figures, with Thamudic inscriptions. Recorded during exploratory field measurements by Andreae and colleagues.","sig":"Extends the known spread of rock art and ancient writing around Al-Quwaiyah.","ex":"Andreae et al. (2021)","disc":["Camel-dominated rock art","Thamudic inscriptions"],"refs":["Andreae, M.O., Al-Amri, A., Al-Jibrin, F.H. & Alsharekh, A.M. (2021). Iconographic and archaeometric studies on the rock art at Musayqira, Al-Quwaiyah Governorate, central Saudi Arabia. Arabian Archaeology and Epigraphy 32(S1), 153–182. https://doi.org/10.1111/aae.12191"],"conf":"Undated in the source; the timeline position is an estimate from the scripts present","ev":"","an":"","val":""},{"id":"camel-site-sakaka","n":"Camel Site (Sakaka)","na":"موقع الجمل (سكاكا)","c":"archaeological","ic":"eye","era":"P","s":"Near-life-size camel reliefs in sandstone","lat":30.0227,"lng":40.2876,"p":"Undated · relief carvings","dr":"Ancient North Arabian and Arabic inscriptions nearby","el":"Near-life-size dromedaries and equids","t0":8000,"t1":2000,"te":"Camels carved life-size","ta":"جمال منحوتة بحجمها الحقيقي","se":"Life-size camels carved in low relief into sandstone spurs, 8 km from Sakaka","sa":"جمال بالحجم الطبيعي منحوتة نحتًا بارزًا في نتوءات رملية على بُعد 8 كم من سكاكا","desc":"Small sandstone spurs of the Wasia Group about 8 km north-east of Sakaka carry low-relief engravings of near-life-size dromedaries and equids, some heavily eroded and others still coated in rock varnish. Two-dimensional petroglyphs and inscriptions in Ancient North Arabian and Arabic scripts are also recorded. Studied with archaeometric measurements of the rock varnish by Andreae and colleagues.","sig":"Rare large-scale relief carving of animals, combining archaeology with the geology of the sandstone and its varnish.","ex":"Andreae et al. (2020)","disc":["Near-life-size relief camels","Rock varnish measured"],"refs":["Andreae, M.O. et al. (2020). Archaeometric studies on the petroglyphs and rock varnish at Kilwa and Sakaka, northern Saudi Arabia. Arabian Archaeology and Epigraphy 31(2), 219–244. https://doi.org/10.1111/aae.12167"],"conf":"Undated in the source; the timeline position is a broad estimate for relief rock art in the region","ev":"","an":"","val":""},{"id":"hudrah-cave","n":"Hudrah Cave (Sakaka)","na":"كهف هدرة (سكاكا)","c":"archaeological","ic":"eye","era":"H","s":"Rock shelter with petroglyphs and Arabic writing","lat":29.9908,"lng":40.1987,"p":"Undated","dr":"Petroglyphs and Arabic inscriptions; nearby well likely Nabataean","el":"About 130 m from Bi’r Saisara","t0":2300,"t1":1000,"te":"The shelter beside the old well","ta":"المأوى بجوار البئر القديمة","se":"A sandstone overhang beside an old well, its ledge marked with engravings and Arabic writing","sa":"حافة صخرية رملية بجوار بئر قديمة، نُقشت على عتبتها رسوم وكتابات عربية","desc":"A small rock shelter beneath a sandstone overhang about 130 m south-south-east of Bi’r Saisara, whose well the study considers likely Nabataean. Petroglyphs and Arabic writing cover the front ledge. Selected inscriptions and rock surfaces were measured archaeometrically by Andreae and colleagues.","sig":"Shows how natural shelters near water were used for writing and rock art around Sakaka.","ex":"Andreae et al. (2020)","disc":["Rock shelter with inscriptions","Next to a likely Nabataean well"],"refs":["Andreae, M.O. et al. (2020). Archaeometric studies on the petroglyphs and rock varnish at Kilwa and Sakaka, northern Saudi Arabia. Arabian Archaeology and Epigraphy 31(2), 219–244. https://doi.org/10.1111/aae.12167"],"conf":"Undated in the source; the timeline position is an estimate from the scripts present","ev":"","an":"","val":""},{"id":"kilwa","n":"Kilwa Rock Art Site","na":"موقع كلوة للفن الصخري","c":"archaeological","ic":"eye","era":"P","s":"Rock-art hills beside a ruined monastery","lat":29.7023,"lng":37.5482,"p":"Several undated phases","dr":"Older and younger petroglyphs; cross engravings","el":"Three hills within about 0.5 km","t0":8000,"t1":1300,"te":"Three hills, three ages of art","ta":"ثلاثة تلال وثلاثة عصور من الفن","se":"In the Jabal Tubaiq, varnish thickness tells older and younger engravings apart on hills beside a ruined monastery","sa":"في جبال الطبيق، تميّز سماكة الورنيش الصخري النقوش الأقدم من الأحدث على تلال بجوار دير مهدّم","desc":"Small inselbergs next to the remains of a monastery in the Jabal Tubaiq. The largest concentration of petroglyphs is on Horsfieldberg; Kleiner Horsfieldberg, about 400 m north-west, carries many engravings read as younger from their thinner rock varnish; Altarberg, about 530 m south, carries mostly cross-shaped engravings. Investigated through rock-varnish sampling and archaeometry.","sig":"One landscape with distinct rock-art traditions and probably different periods side by side.","ex":"Andreae et al. (2020)","disc":["Varnish thickness separates phases","Cross engravings beside a monastery"],"refs":["Andreae, M.O. et al. (2020). Archaeometric studies on the petroglyphs and rock varnish at Kilwa and Sakaka, northern Saudi Arabia. Arabian Archaeology and Epigraphy 31(2), 219–244. https://doi.org/10.1111/aae.12167"],"conf":"Undated in the source; the timeline position is a broad estimate","ev":"","an":"","val":""},{"id":"jabal-tubaiq-hill","n":"Jabal Tubaiq Hill Rock Art Site","na":"موقع تل جبل الطبيق للفن الصخري","c":"archaeological","ic":"eye","era":"H","s":"Hismaic inscriptions and camel petroglyphs","lat":29.6092,"lng":37.5908,"p":"Undated","dr":"Hismaic script","el":"Inscriptions around a hilltop on the track to Kilwa","t0":2600,"t1":1500,"te":"A hill nobody had written about","ta":"تلّ لم يكتب عنه أحد","se":"Camels and Hismaic writing around a hilltop on the road to Kilwa, first reported in 2020","sa":"جمال وكتابات حسمائية حول قمة تل على طريق كلوة، وُثّقت أول مرة عام 2020","desc":"A hill on the track to Kilwa in the Jabal Tubaiq with several inscriptions and petroglyphs around its top. The inscriptions are in Hismaic script and camels are the most common motif. Identified during fieldwork by Andreae and colleagues, who noted it had not been reported before.","sig":"A newly documented rock-art and inscription site in northern Saudi Arabia.","ex":"Andreae et al. (2020)","disc":["First reported in 2020","Hismaic inscriptions"],"refs":["Andreae, M.O. et al. (2020). Archaeometric studies on the petroglyphs and rock varnish at Kilwa and Sakaka, northern Saudi Arabia. Arabian Archaeology and Epigraphy 31(2), 219–244. https://doi.org/10.1111/aae.12167"],"conf":"Undated in the source; the timeline position is an estimate from the scripts present","ev":"","an":"","val":""},{"id":"jebel-qattar-jq101","n":"JQ-101 (Jebel Qattar)","na":"JQ-101 (جبل قطار)","c":"archaeological","ic":"trench","era":"P","s":"Pre-Pottery Neolithic stone-tool site","lat":28.0184,"lng":41.0626,"p":"Pre-Pottery Neolithic","dr":"Pre-Pottery Neolithic","el":"About 250 × 120 m at 810–820 m altitude","t0":10200,"t1":9000,"te":"Strangers from the Levant","ta":"غرباء من بلاد الشام","se":"Stone tools at the foot of Jebel Qattar show Levantine Neolithic people reached the Nefud","sa":"أدوات حجرية عند سفح جبل قطار تُظهر أن شعوب العصر الحجري الحديث الشامية وصلت إلى النفود","desc":"A lithic site in a small depression at the north-eastern foot of Jebel Qattar in the Jubbah basin, at about 810–820 m, spread over about 250 × 120 m (about 30,000 m²). It holds a large stone-tool assemblage, with rock art of animals and people on nearby boulders and cliffs. Crassard and colleagues present it as the first evidence of a Pre-Pottery Neolithic incursion into the Nefud Desert. Separate from the Jubbah rock-art World Heritage component about 15 km away.","sig":"Evidence that Levantine Neolithic groups reached deep into northern Arabia.","ex":"Crassard et al. (2013)","disc":["First Pre-Pottery Neolithic site in the Nefud","About 30,000 m² of finds"],"refs":["Crassard, R. et al. (2013). Beyond the Levant: First Evidence of a Pre-Pottery Neolithic Incursion into the Nefud Desert, Saudi Arabia. PLOS ONE 8(7), e68061. https://doi.org/10.1371/journal.pone.0068061"],"conf":"Age range is the general Pre-Pottery Neolithic span, as discussed in the source","ev":"","an":"","val":""},{"id":"khall-amayshan-4","n":"Khall Amayshan-4 (KAM-4)","na":"خل عميشان 4","c":"archaeological","ic":"river","era":"P","s":"Stacked ancient lakes with 400,000 years of human visits","lat":28.028,"lng":39.352,"p":"Middle and Late Pleistocene","dr":"Lake deposits dated 412 ± 87 ka, 337 ± 39 ka and 306 ± 47 ka","el":"About 700 × 200 m, six lake deposits","t0":412000,"t1":55000,"te":"Six lakes in the desert","ta":"ست بحيرات في الصحراء","se":"Six buried lakes in the Nefud record people returning again and again over 400,000 years","sa":"ست بحيرات مدفونة في النفود تسجّل عودة البشر مرة بعد مرة على مدى 400 ألف سنة","desc":"Discovered in 2013 by the Palaeodeserts Project in the western Nefud: superimposed palaeolake deposits in an interdunal depression covering about 117,000 m² (700 × 200 m). Six lake deposits hold stone tools and animal fossils; four 2 × 2 m trenches in the Northwest Lake recovered buried finds. Luminescence and U-series dating give lake phases of 412 ± 87, 337 ± 39 and 306 ± 47 thousand years and a sequence of occupations across about 400,000 years.","sig":"One of the most detailed records of repeated human dispersal into Arabia as lakes came and went.","ex":"Palaeodeserts Project; Groucutt et al. (2021)","disc":["Six superimposed lake deposits","Occupations over about 400,000 years"],"refs":["Groucutt, H.S. et al. (2021). Multiple hominin dispersals into Southwest Asia over the past 400,000 years. Nature 597, 376–380. https://doi.org/10.1038/s41586-021-03863-y"],"conf":"Youngest phase (≈55 ka) taken from the same study","ev":"","an":"","val":""},{"id":"jilh-type-section","n":"Jilh Formation Type Section (Jilh al’Ishar)","na":"المقطع النموذجي لتكوين الجلة (جلة العشار)","c":"geological","ic":"cliff","era":"D","s":"Reference section of the Triassic in central Arabia","lat":24.0633,"lng":45.7667,"p":"Middle to Late Triassic","dr":"Middle–Late Triassic","el":"About 326 m thick","t0":245000000,"t1":210000000,"te":"The rock book of the Triassic","ta":"كتاب الصخر من العصر الترياسي","se":"Some 326 m of sandstone, clay, limestone and dolomite that geologists use to read Arabia’s Triassic","sa":"نحو 326 م من الحجر الرملي والطين والجيري والدولوميت يعتمد عليها الجيولوجيون لقراءة العصر الترياسي في الجزيرة العربية","desc":"The formal type section of the Jilh Formation, defined at Jilh al’Ishar and measured from 24°03′48″N, 45°46′00″E to 24°11′06″N, 45°51′30″E. About 326 m thick, it comprises cross-bedded sandstone, clay interbeds, limestone and dolomite recording changing depositional settings, with fossils used to fix its Middle to Late Triassic age.","sig":"The reference against which Triassic rocks across the region are correlated.","ex":"Le Nindre et al. (2023)","disc":["Formal type section","About 326 m of strata"],"refs":["Le Nindre, Y.-M., Vaslet, D., Vrielynck, B., Krystyn, L., Manivit, J., Memesh, A. & Davies, R.B. (2023). The Middle to Late Triassic of Central Saudi Arabia with emphasis on the Jilh Formation. Part I. Comptes Rendus Géoscience. https://doi.org/10.5802/crgeos.217"],"conf":"Numeric ages are the standard span of the Middle–Late Triassic","ev":"","an":"","val":""},{"id":"banban-section","n":"Banban Section","na":"مقطع بنبان","c":"geological","ic":"cliff","era":"D","s":"Lower Cretaceous limestone section north of Riyadh","lat":25.015,"lng":46.6208,"p":"Early Cretaceous (Berriasian–Valanginian)","dr":"c. 143–136 million years ago","el":"79 m of Silayy and Yamamah formations","t0":143000000,"t1":136000000,"te":"When the sea came to Riyadh","ta":"حين وصل البحر إلى الرياض","se":"79 m of limestone 40 km north of Riyadh record the sea rising and falling 140 million years ago","sa":"79 م من الحجر الجيري على بُعد 40 كم شمال الرياض تسجّل ارتفاع البحر وانحساره قبل 140 مليون سنة","desc":"A measured 79 m Lower Cretaceous succession about 40 km north of Riyadh in the Silayy and Yamamah formations, mostly carbonates with minor siliciclastic beds. Nagm and colleagues sampled it to study facies and sequence stratigraphy, identifying transgressive–regressive cycles, the first spanning about 143 to 138 million years ago.","sig":"A located reference for Early Cretaceous sea-level change in central Arabia.","ex":"Nagm et al. (2018)","disc":["Two sea-level cycles","Silayy and Yamamah formations"],"refs":["Nagm, E., Bamousa, A., Memesh, A., Babikir, I.A.A. & Dini, S. (2018). Relative sea-level changes and sedimentary facies development of the lowermost Cretaceous (Berriasian–Valanginian) cycles in the north of Ar Riyad city, Saudi Arabia. Journal of Asian Earth Sciences. https://doi.org/10.1016/j.jseaes.2018.05.036"],"conf":"","ev":"","an":"","val":""},{"id":"harrat-kishb-kites","n":"Harrat Kishb desert kites","na":"مصائد الطائرات الورقية في حرة كشب","c":"archaeological","ic":"wall","era":"P","s":"Prehistoric hunting traps on a lava field · UNESCO Tentative List","lat":23.399,"lng":39.8496,"p":"Prehistoric","dr":"Several building phases; not precisely dated","el":"More than 20 kites","t0":9000,"t1":5000,"te":"Stone funnels for catching gazelles","ta":"أقماع حجرية لصيد الغزلان","se":"Long stone walls on a lava field once steered herds of wild animals into hunting pens","sa":"جدران حجرية طويلة على حرة بركانية كانت توجّه قطعان الحيوانات البرية إلى حظائر الصيد","desc":"A volcanic landscape south-east of Madinah where surveys have found more than 20 desert kites and other prehistoric stone structures. The kites have shallower guiding-wall angles than those of Harrat Khaybar and use the natural relief in their design; several construction phases show repeated use and rebuilding, and meandering walls may be early kite-like forms. Component 04 of the Saudi Tentative List nomination.","sig":"Evidence of organised prehistoric hunting and of people reshaping volcanic land.","ex":"Saudi Heritage Commission; UNESCO Tentative List 2023","disc":["More than 20 desert kites","Several building phases"],"refs":["Permanent Delegation of Saudi Arabia to UNESCO (2023). Prehistoric Stone Structures in Saudi Arabia. UNESCO World Heritage Tentative List, ref. 6636. https://whc.unesco.org/en/tentativelists/6636/"],"conf":"Not dated in the source; the timeline position is a broad estimate for prehistoric stone structures in Arabia","ev":"","an":"","val":""},{"id":"rohab-circles","n":"Rohab stone circles (Tabuk)","na":"دوائر رهاب الحجرية (تبوك)","c":"archaeological","ic":"wall","era":"P","s":"Overlapping prehistoric stone circles · UNESCO Tentative List","lat":27.4231,"lng":36.7563,"p":"Prehistoric","dr":"Possibly Neolithic or later; not dated","el":"Clustered overlapping circles","t0":8000,"t1":4000,"te":"Rings that overlap like a drawing","ta":"حلقات متداخلة كأنها رسم","se":"Stone circles overlapping one another in the Tabuk desert, perhaps the floors of old camps","sa":"دوائر حجرية يتداخل بعضها في بعض في صحراء تبوك، ربما أرضيات مخيمات قديمة","desc":"Part of the Tabuk component of the Saudi prehistoric stone-structures nomination. The Tentative List file describes a cluster of aggregated, overlapping circular stone structures interpreted as possible remains of temporary or semi-permanent settlements, in a region that also holds rock art and Stone Age tools. Their date and function remain uncertain.","sig":"A clue to how prehistoric people organised and reused camps in the Tabuk landscape.","ex":"UNESCO Tentative List 2023","disc":["Overlapping stone circles","Possibly settlement floors"],"refs":["Permanent Delegation of Saudi Arabia to UNESCO (2023). Prehistoric Stone Structures in Saudi Arabia. UNESCO World Heritage Tentative List, ref. 6636. https://whc.unesco.org/en/tentativelists/6636/"],"conf":"Not dated in the source; the timeline position is a broad estimate for prehistoric stone structures in Arabia","ev":"","an":"","val":""},{"id":"hait-pendants","n":"Ha’it Oasis stone structures","na":"المنشآت الحجرية في واحة الحائط","c":"archaeological","ic":"wall","era":"P","s":"Pendant and keyhole monuments · UNESCO Tentative List","lat":25.9987,"lng":40.4917,"p":"Prehistoric, before the Bronze Age","dr":"Not dated","el":"Concentrated parallel groups","t0":7500,"t1":4500,"te":"Keyholes in the desert","ta":"ثقوب مفاتيح في الصحراء","se":"Rows of keyhole- and pendant-shaped stone monuments line an oasis on the old Mesopotamia–Levant routes","sa":"صفوف من المنشآت الحجرية على شكل ثقب المفتاح والقلادة تحيط بواحة على طرق قديمة بين الرافدين والشام","desc":"An oasis in Hail Province on ancient routes linking Mesopotamia and the Levant. Its landscape holds many pendant- and keyhole-shaped stone structures in concentrated, often parallel groups, which the Tentative List file places before the Bronze Age civilisations of northern Arabia. Component 07 of the nomination.","sig":"Shows communities shaping northern Arabia’s landscape before the first towns.","ex":"UNESCO Tentative List 2023","disc":["Pendant and keyhole monuments","Parallel groups"],"refs":["Permanent Delegation of Saudi Arabia to UNESCO (2023). Prehistoric Stone Structures in Saudi Arabia. UNESCO World Heritage Tentative List, ref. 6636. https://whc.unesco.org/en/tentativelists/6636/"],"conf":"Not dated in the source; the timeline position is a broad estimate for prehistoric stone structures in Arabia","ev":"","an":"","val":""},{"id":"harrat-nawasif-kites","n":"Harrat Nawasif kites","na":"مصائد حرة النواصف","c":"archaeological","ic":"wall","era":"P","s":"Hundreds of desert kites · UNESCO Tentative List","lat":21.319,"lng":42.562,"p":"Prehistoric","dr":"Not dated","el":"One kite 1.4 km long enclosing over 500,000 m²","t0":9000,"t1":5000,"te":"A trap the size of seventy football pitches","ta":"مصيدة بحجم سبعين ملعب كرة قدم","se":"Several hundred hunting kites ring a lava field east of Makkah; one encloses half a square kilometre","sa":"مئات من مصائد الصيد تحيط بحرة بركانية شرق مكة؛ إحداها تحيط بنصف كيلومتر مربع","desc":"A volcanic field about 250 km east of Makkah, on old west-to-east drainage lines, with kites, cairns, pendants and wheels. Several hundred desert kites cluster on the edges of the lava and around small wadis, most with two gently converging walls and simple end enclosures. One measures about 1,400 m long, with about 3,000 m of walls enclosing more than 500,000 m². Component 08 of the nomination.","sig":"Among the largest prehistoric hunting structures known, evidence of large-scale cooperative hunting.","ex":"UNESCO Tentative List 2023","disc":["Several hundred kites","One kite encloses 500,000 m²"],"refs":["Permanent Delegation of Saudi Arabia to UNESCO (2023). Prehistoric Stone Structures in Saudi Arabia. UNESCO World Heritage Tentative List, ref. 6636. https://whc.unesco.org/en/tentativelists/6636/"],"conf":"Not dated in the source; the timeline position is a broad estimate for prehistoric stone structures in Arabia","ev":"","an":"","val":""},{"id":"hisma-stone-structures","n":"Hisma stone circles and cairns","na":"دوائر حسمى الحجرية وركامها","c":"archaeological","ic":"wall","era":"P","s":"Multi-period monuments on an old mountain corridor · UNESCO Tentative List","lat":28.4232,"lng":35.7306,"p":"Prehistoric to early Islamic","dr":"Several phases","el":"Circles from a few metres to about 140 m across","t0":9000,"t1":1300,"te":"The mountain road of a thousand circles","ta":"طريق الجبل ذو الألف دائرة","se":"Stone circles up to 140 m wide, cairns and Thamudic writing mark a corridor west of Tabuk used for millennia","sa":"دوائر حجرية يبلغ عرضها 140 م وركام وكتابات ثمودية تحدد ممرًا غرب تبوك استُخدم آلاف السنين","desc":"The Hisma mountains west of Tabuk, along an ancient trade corridor, hold many prehistoric circular stone structures and cairns, from a few metres to about 140 m across, some isolated and some overlapping in linked groups. Thamudic inscriptions, graffiti and remains from antiquity and the early Islamic period record later travellers. Component 09 of the nomination; distinct from the Jabal al-Lawz geological site.","sig":"A landscape where prehistoric monuments and later travel routes overlap over several millennia.","ex":"UNESCO Tentative List 2023","disc":["Circles up to 140 m","Thamudic inscriptions"],"refs":["Permanent Delegation of Saudi Arabia to UNESCO (2023). Prehistoric Stone Structures in Saudi Arabia. UNESCO World Heritage Tentative List, ref. 6636. https://whc.unesco.org/en/tentativelists/6636/"],"conf":"Not dated in the source; the timeline position is a broad estimate for prehistoric stone structures in Arabia","ev":"","an":"","val":""},{"id":"jabal-shada","n":"Jabal Shada al-A’la Nature Reserve","na":"محمية جبل شدا الأعلى","c":"ecology","ic":"plant","era":"N","s":"Granite mountain reserve with about 500 plant species","lat":19.8456,"lng":41.3178,"p":"Present","dr":"Protected 2002","el":"68.62 km², up to about 2,222 m","t0":24,"t1":0,"te":"The granite island of plants","ta":"جزيرة النباتات الجرانيتية","se":"An isolated granite mountain in Al-Bahah sheltering about 500 plant species and flies new to Saudi Arabia","sa":"جبل جرانيتي منعزل في الباحة يأوي نحو 500 نوع نباتي وذبابًا لم يُسجَّل في السعودية من قبل","desc":"An isolated granite massif in Al-Mekhwa District, Al-Bahah, protected in 2002 over 68.62 km² and rising to about 2,222 m. About 500 plant species are recorded, including endemic and Afrotropical relict taxa. A survey found 119 fly species in 87 genera and 30 families, 14 of them first records for Saudi Arabia; the reserve also supports south-west Arabian mountain wildlife. Reported as IUCN category II by the National Center for Wildlife.","sig":"A centre of plant and insect diversity in south-western Arabia with African affinities.","ex":"National Center for Wildlife; El-Hawagry et al. (2016)","disc":["About 500 plant species","14 fly species new to Saudi Arabia"],"refs":["El-Hawagry, M.S., Abdel-Dayem, M.S., Elgharbawy, A.A. & Al Dhafer, H.M. (2016). A preliminary account of the fly fauna in Jabal Shada al-A’la Nature Reserve, Saudi Arabia, with new records and biogeographical remarks. ZooKeys 636, 107–139. https://doi.org/10.3897/zookeys.636.9905"],"conf":"Coordinates are the centre of the published reserve bounds","ev":"","an":"","val":""},{"id":"al-taweelah-island","n":"Al Taweelah Island","na":"جزيرة الطويلة","c":"ecology","ic":"mangrove","era":"N","s":"Red Sea mangroves and seagrass building their own ground","lat":22.2667,"lng":39.0833,"p":"Present","dr":"Sampled 2015","el":"Mangrove sediments about 97% carbonate","t0":11,"t1":0,"te":"Mangroves that grow their own floor","ta":"مانغروف يبني أرضه بنفسه","se":"Red Sea mangroves and seagrass whose mud is almost all shell carbonate, helping them keep pace with the sea","sa":"مانغروف وأعشاب بحرية في البحر الأحمر طينها كله تقريبًا من كربونات الأصداف، ما يساعدها على مجاراة ارتفاع البحر","desc":"A nearshore island on the central Red Sea coast with mangrove forest and seagrass meadows. Saderne and colleagues took eight mangrove and three seagrass cores in 2015; the mangrove sediment was about 97% calcium carbonate by dry weight. They measured sediment build-up and inorganic carbon burial; coastal engineering was reported on the shore facing the island in the early 2010s.","sig":"Field evidence of how arid-coast mangroves and seagrass build sediment and store carbon.","ex":"Saderne et al. (2018)","disc":["About 97% carbonate sediment","Mangrove and seagrass cores"],"refs":["Saderne, V. et al. (2018). Accumulation of Carbonates Contributes to Coastal Vegetated Ecosystems Keeping Pace With Sea Level Rise in an Arid Region (Arabian Peninsula). Journal of Geophysical Research: Biogeosciences 123(5), 1498–1510. https://doi.org/10.1029/2017JG004288"],"conf":"Coordinates given to the nearest minute in the source","ev":"","an":"","val":""},{"id":"khor-almesenaa","n":"Khor Almesena’a","na":"خور المسناة","c":"ecology","ic":"mangrove","era":"N","s":"Red Sea lagoon with mangroves and seagrass","lat":22.3667,"lng":39.1167,"p":"Present","dr":"Sampled 2015","el":"Mangrove sediments about 76% carbonate","t0":11,"t1":0,"te":"The lagoon that stores the sea","ta":"الخور الذي يخزّن البحر","se":"A Red Sea lagoon where mangroves and seagrass trap carbonate mud","sa":"خور في البحر الأحمر تحبس فيه أشجار المانغروف والأعشاب البحرية الطين الكربوني","desc":"A coastal lagoon on the central Red Sea coast with mangrove forest and seagrass meadows. Eight mangrove and ten seagrass cores were taken in 2015; mangrove sediment was about 76% calcium carbonate by dry weight. Part of a comparison of sediment build-up, carbonate storage and carbon burial along the Saudi Red Sea coast.","sig":"A documented example of carbonate accumulation in both mangrove and seagrass under an arid climate.","ex":"Saderne et al. (2018)","disc":["About 76% carbonate sediment","Mangrove and seagrass cores"],"refs":["Saderne, V. et al. (2018). Accumulation of Carbonates Contributes to Coastal Vegetated Ecosystems Keeping Pace With Sea Level Rise in an Arid Region (Arabian Peninsula). Journal of Geophysical Research: Biogeosciences 123(5), 1498–1510. https://doi.org/10.1029/2017JG004288"],"conf":"Coordinates given to the nearest minute in the source","ev":"","an":"","val":""},{"id":"khor-al-baqila","n":"Khor Al-Baqila","na":"خور البقيلة","c":"ecology","ic":"mangrove","era":"N","s":"Red Sea mangrove lagoon beside an industrial terminal","lat":22.7333,"lng":39.0,"p":"Present","dr":"Sampled 2015","el":"Mangrove sediments about 57% carbonate","t0":11,"t1":0,"te":"Mangroves next to the terminal","ta":"مانغروف بجوار المرفأ","se":"A mangrove lagoon on the Red Sea, its southern side reshaped by a petrochemical terminal since 1981","sa":"خور مانغروف على البحر الأحمر غيّر مرفأ بتروكيماويات جانبه الجنوبي منذ 1981","desc":"A coastal lagoon on the central Red Sea coast where six mangrove cores were taken in 2015; the sediment was about 57% calcium carbonate by dry weight. Sediment build-up and inorganic carbon storage were measured. The southern side of the embayment was heavily altered after conversion to a petrochemical terminal from 1981, as documented in the study.","sig":"Baseline measurements from a mangrove affected by major coastal industry.","ex":"Saderne et al. (2018)","disc":["About 57% carbonate sediment","Industrial coast since 1981"],"refs":["Saderne, V. et al. (2018). Accumulation of Carbonates Contributes to Coastal Vegetated Ecosystems Keeping Pace With Sea Level Rise in an Arid Region (Arabian Peninsula). Journal of Geophysical Research: Biogeosciences 123(5), 1498–1510. https://doi.org/10.1029/2017JG004288"],"conf":"Coordinates given to the nearest minute in the source","ev":"","an":"","val":""},{"id":"khor-al-kharrar","n":"Khor Al-Kharrar","na":"خور الخرار","c":"ecology","ic":"mangrove","era":"N","s":"Red Sea lagoon with mangroves and seagrass","lat":22.95,"lng":38.85,"p":"Present","dr":"Sampled 2015","el":"Carbonate about 73% (mangrove) and 64% (seagrass)","t0":11,"t1":0,"te":"Two gardens under the tide","ta":"حديقتان تحت المد","se":"Mangroves and seagrass side by side in a Red Sea lagoon, both building ground from shell carbonate","sa":"مانغروف وأعشاب بحرية جنبًا إلى جنب في خور بالبحر الأحمر، يبنيان الأرض من كربونات الأصداف","desc":"A coastal lagoon on the central Red Sea coast where both mangrove forest and seagrass meadows were studied: seven mangrove and ten seagrass cores in 2015. Mangrove sediment was about 73% and seagrass sediment about 64% calcium carbonate by dry weight. The study assessed sediment build-up and carbon burial in both habitats.","sig":"Side-by-side measurements of how two coastal habitats build sediment.","ex":"Saderne et al. (2018)","disc":["Mangrove and seagrass compared","73% and 64% carbonate"],"refs":["Saderne, V. et al. (2018). Accumulation of Carbonates Contributes to Coastal Vegetated Ecosystems Keeping Pace With Sea Level Rise in an Arid Region (Arabian Peninsula). Journal of Geophysical Research: Biogeosciences 123(5), 1498–1510. https://doi.org/10.1029/2017JG004288"],"conf":"Coordinates given to the nearest minute in the source","ev":"","an":"","val":""},{"id":"jebel-qattar-jq1","n":"Jebel Qattar 1 (JQ-1)","na":"جبل قطار 1 (JQ-1)","c":"archaeological","ic":"trench","era":"P","s":"Dated Middle Palaeolithic site on the Jubbah palaeolake","lat":28.0148,"lng":41.06,"p":"Middle Palaeolithic","dr":"OSL ages 211 ± 16, 95 ± 7 and 75 ± 5 ka","el":"Sands, palaeosols and calcretes","t0":211000,"t1":75000,"te":"Tools on the shore of a vanished lake","ta":"أدوات على شاطئ بحيرة مختفية","se":"Levallois stone tools in an old soil on the shore of the lost Jubbah lake, dated to about 75,000 years","sa":"أدوات حجرية لوفالوازية في تربة قديمة على شاطئ بحيرة جبة المفقودة، عمرها نحو 75 ألف سنة","desc":"A stratified Middle Palaeolithic site on sediments near the southern edge of the Jubbah palaeolake. Excavation exposed aeolian sands, palaeosols and calcretes, with stone tools in the upper palaeosol, including Levallois flakes and retouched tools. OSL dating gave 211 ± 16, 95 ± 7 and 75 ± 5 thousand years for the sequence. About 0.5 km from the later Neolithic site JQ-101 on the same hill.","sig":"A well-dated record of human presence and changing climate in northern Arabia.","ex":"Petraglia et al. (2012)","disc":["OSL dates 211–75 ka","Levallois tools"],"refs":["Petraglia, M.D. et al. (2012). Hominin Dispersal into the Nefud Desert and Middle Palaeolithic Settlement along the Jubbah Palaeolake, Northern Arabia. PLOS ONE 7(11), e49840. https://doi.org/10.1371/journal.pone.0049840"],"conf":"","ev":"","an":"","val":""},{"id":"jebel-katefeh-jkf1","n":"Jebel Katefeh 1 (JKF-1)","na":"جبل كتيفة 1 (JKF-1)","c":"archaeological","ic":"trench","era":"P","s":"Middle Palaeolithic camp on an old dune by a lake","lat":27.9218,"lng":40.805,"p":"Middle Palaeolithic","dr":"Middle Palaeolithic","el":"923 surface artefacts","t0":100000,"t1":55000,"te":"A camp on the dune above the lake","ta":"مخيم على الكثيب فوق البحيرة","se":"Stone-tool makers camped on an ancient dune above a shallow lake south-west of Jubbah","sa":"صانعو الأدوات الحجرية خيّموا على كثيب قديم فوق بحيرة ضحلة جنوب غرب جبة","desc":"A Middle Palaeolithic site on a sedimentary mound beside a former lake basin south-west of Jubbah. The mound preserves old dune sands overlain by lake silts and capped by calcrete; excavation found an artefact horizon with Levallois products, and 923 artefacts were collected from the surface. The stratigraphy points to occupation on an ancient dune overlooking a shallow lake.","sig":"Evidence of people making tools around former Nefud lakes.","ex":"Petraglia et al. (2012)","disc":["923 surface artefacts","Camp on an old dune"],"refs":["Petraglia, M.D. et al. (2012). Hominin Dispersal into the Nefud Desert and Middle Palaeolithic Settlement along the Jubbah Palaeolake, Northern Arabia. PLOS ONE 7(11), e49840. https://doi.org/10.1371/journal.pone.0049840"],"conf":"Not numerically dated in the source; placed within the Middle Palaeolithic phases dated at nearby JQ-1","ev":"","an":"","val":""},{"id":"jebel-umm-sanman-jsm1","n":"Jebel Umm Sanman 1 (JSM-1)","na":"جبل أم سنمان 1 (JSM-1)","c":"archaeological","ic":"trench","era":"P","s":"Middle Palaeolithic quartzite workshop by the Jubbah lake","lat":27.9763,"lng":40.9245,"p":"Middle Palaeolithic","dr":"Middle Palaeolithic","el":"Finds over about 160 × 75 m","t0":100000,"t1":55000,"te":"The yellow-stone workshop","ta":"ورشة الحجر الأصفر","se":"Levallois cores of yellow quartzite on a hill overlooking the old Jubbah lake","sa":"نوى لوفالوازية من الكوارتزيت الأصفر على تل يطل على بحيرة جبة القديمة","desc":"A site on the south-eastern edge of Jebel Umm Sanman overlooking the western side of the northern Jubbah palaeolake, with finds across about 160 × 75 m. Excavation found artefacts in two layers, including Levallois cores and flakes of a distinctive yellow fine-grained quartzite. Middle Palaeolithic; separate from the later rock-art panels of the Jubbah World Heritage component on the same mountain.","sig":"Shows stone-tool production and raw-material use around the palaeolake.","ex":"Petraglia et al. (2012)","disc":["Yellow quartzite Levallois cores","Finds in two layers"],"refs":["Petraglia, M.D. et al. (2012). Hominin Dispersal into the Nefud Desert and Middle Palaeolithic Settlement along the Jubbah Palaeolake, Northern Arabia. PLOS ONE 7(11), e49840. https://doi.org/10.1371/journal.pone.0049840"],"conf":"Not numerically dated in the source; placed within the Middle Palaeolithic phases dated at nearby JQ-1","ev":"","an":"","val":""},{"id":"king-salman-tabuk","n":"King Salman Royal Reserve – Tabuk sampling site","na":"محمية الملك سلمان الملكية – موقع عيّنات تبوك","c":"ecology","ic":"plant","era":"N","s":"Hidden microbes that help desert plants survive","lat":28.3835,"lng":36.5662,"p":"Present","dr":"Published 2026","el":"Highest microbial diversity of the three areas","t0":1,"t1":0,"te":"The richest soil life of the reserve","ta":"أغنى حياة ميكروبية في المحمية","se":"Desert acacia, saxaul and Christ’s thorn here carry the most diverse root microbes found in the study","sa":"السمر والرمث والسدر هنا تحمل أكثر ميكروبات الجذور تنوعًا في الدراسة","desc":"A sampling point in the Tabuk sector of the King Salman bin Abdulaziz Royal Natural Reserve. Researchers sampled roots and the soil around them from three native desert plants (Vachellia gerrardii, Haloxylon salicornicum and Ziziphus spina-christi) and identified the bacteria and fungi using 16S rRNA and ITS DNA sequencing, comparing Tabuk, Hail and Arar. Tabuk had the highest overall microbial diversity of the three regions.","sig":"Shows how plant–microbe partnerships support vegetation in an arid landscape.","ex":"Alhasani et al. (2026)","disc":["Three desert plants","Bacteria and fungi DNA-sequenced"],"refs":["Alhasani, F.M., Rajab, M.H., Sulieman, A.M.E., Alanazi, N.A., Aljabry, N., Alwahibi, M.S. & Mammdouh, A. (2026). Diversity and ecological drivers of rhizospheric and endophytic microbiomes of desert plants in King Salman Reserve, Saudi Arabia. Journal of King Saud University – Science 38. https://doi.org/10.25259/JKSUS_1695_2025"],"conf":"Exact sampling point from the source","ev":"","an":"","val":""},{"id":"king-salman-hail","n":"King Salman Royal Reserve – Hail sampling site","na":"محمية الملك سلمان الملكية – موقع عيّنات حائل","c":"ecology","ic":"plant","era":"N","s":"Hidden microbes that help desert plants survive","lat":27.5114,"lng":41.7208,"p":"Present","dr":"Published 2026","el":"Intermediate microbial diversity","t0":1,"t1":0,"te":"The middle of the microbe gradient","ta":"وسط تدرّج الميكروبات","se":"Root microbes of desert plants near Hail sit between the rich Tabuk and the tough Arar communities","sa":"ميكروبات جذور النباتات الصحراوية قرب حائل تقع بين مجتمعات تبوك الغنية ومجتمعات عرعر المتحمّلة","desc":"A sampling point in the Hail sector of the King Salman bin Abdulaziz Royal Natural Reserve. Researchers sampled roots and the soil around them from three native desert plants (Vachellia gerrardii, Haloxylon salicornicum and Ziziphus spina-christi) and identified the bacteria and fungi using 16S rRNA and ITS DNA sequencing, comparing Tabuk, Hail and Arar. Hail showed intermediate microbial diversity in the comparison.","sig":"Regional evidence of how environment shapes the microbes of desert plants.","ex":"Alhasani et al. (2026)","disc":["Three desert plants","Bacteria and fungi DNA-sequenced"],"refs":["Alhasani, F.M., Rajab, M.H., Sulieman, A.M.E., Alanazi, N.A., Aljabry, N., Alwahibi, M.S. & Mammdouh, A. (2026). Diversity and ecological drivers of rhizospheric and endophytic microbiomes of desert plants in King Salman Reserve, Saudi Arabia. Journal of King Saud University – Science 38. https://doi.org/10.25259/JKSUS_1695_2025"],"conf":"Exact sampling point from the source","ev":"","an":"","val":""},{"id":"king-salman-arar","n":"King Salman Royal Reserve – Arar sampling site","na":"محمية الملك سلمان الملكية – موقع عيّنات عرعر","c":"ecology","ic":"plant","era":"N","s":"Hidden microbes that help desert plants survive","lat":30.9599,"lng":41.0596,"p":"Present","dr":"Published 2026","el":"Enriched in stress-tolerant bacteria (Rubrobacter, Truepera)","t0":1,"t1":0,"te":"Microbes built for hardship","ta":"ميكروبات خُلقت للمشقة","se":"In the harsh north near Arar, desert plant roots host tough bacteria such as Rubrobacter and Truepera","sa":"في الشمال القاسي قرب عرعر تأوي جذور النباتات الصحراوية بكتيريا متحمّلة مثل روبروباكتر وتروبيرا","desc":"A sampling point in the Arar sector of the King Salman bin Abdulaziz Royal Natural Reserve. Researchers sampled roots and the soil around them from three native desert plants (Vachellia gerrardii, Haloxylon salicornicum and Ziziphus spina-christi) and identified the bacteria and fungi using 16S rRNA and ITS DNA sequencing, comparing Tabuk, Hail and Arar. Arar showed enrichment of stress-associated bacterial genera such as Rubrobacter and Truepera.","sig":"Evidence of microbial adaptation to the most severe conditions in the study.","ex":"Alhasani et al. (2026)","disc":["Three desert plants","Bacteria and fungi DNA-sequenced"],"refs":["Alhasani, F.M., Rajab, M.H., Sulieman, A.M.E., Alanazi, N.A., Aljabry, N., Alwahibi, M.S. & Mammdouh, A. (2026). Diversity and ecological drivers of rhizospheric and endophytic microbiomes of desert plants in King Salman Reserve, Saudi Arabia. Journal of King Saud University – Science 38. https://doi.org/10.25259/JKSUS_1695_2025"],"conf":"Exact sampling point from the source","ev":"","an":"","val":""},{"id":"al-qana-1","n":"Al Qana-1 (QAN-1)","na":"القنا 1 (QAN-1)","c":"archaeological","ic":"trench","era":"P","s":"Middle Palaeolithic rhyolite workshop on the southern Nefud","lat":27.7665,"lng":41.4119,"p":"Middle Palaeolithic","dr":"Middle Palaeolithic","el":"Two artefact concentrations","t0":100000,"t1":55000,"te":"Toolmakers at the edge of the sands","ta":"صانعو الأدوات على حافة الرمال","se":"Stone tools made of rhyolite on an old alluvial fan at the southern edge of the Nefud","sa":"أدوات حجرية من الريوليت على مروحة فيضية قديمة عند الحافة الجنوبية للنفود","desc":"A Middle Palaeolithic site near Al Qana village on the southern margin of the Nefud Desert, on the far end of an alluvial fan spreading from mountains to the south. Two artefact concentrations were found, with many Middle Palaeolithic pieces. Most are rhyolite and show tools were made on the spot, mainly by discoidal flaking with a smaller Levallois component.","sig":"Shows how Middle Palaeolithic people chose stone and made tools in the southern Nefud.","ex":"Groucutt et al. (2016)","disc":["Rhyolite tools made on site","Discoidal and Levallois flaking"],"refs":["Groucutt, H.S. et al. (2016). The Middle Palaeolithic of the Nejd, Saudi Arabia. Journal of Field Archaeology 41(2), 131–147. https://doi.org/10.1080/00934690.2016.1156928"],"conf":"Not numerically dated in the source; placed within the broad Middle Palaeolithic span used for other undated Arabian sites. Coordinates about ±1 km","ev":"","an":"","val":""},{"id":"az-zuaynah-2","n":"Az Zu’aynah-2 (AZA-2)","na":"الزعينة 2 (AZA-2)","c":"archaeological","ic":"trench","era":"P","s":"Middle Palaeolithic tools beside an old river plain","lat":24.3506,"lng":44.9915,"p":"Middle Palaeolithic","dr":"Middle Palaeolithic","el":"Igneous-stone artefacts by a braided wadi","t0":100000,"t1":55000,"te":"Tools by the ancient river","ta":"أدوات عند النهر القديم","se":"Levallois cores beside a broad wadi east of Dawadmi, where rock was taken straight from the hillside","sa":"نوى لوفالوازية بجانب وادٍ عريض شرق الدوادمي، حيث أُخذ الحجر مباشرة من سفح التل","desc":"A Middle Palaeolithic site east of Dawadmi at the western end of a chain of small hills beside a broad wadi with a braided river plain and seasonal channels. Artefacts lie on slopes at the edge of the floodplain close to bedrock that supplied the stone. Most are fine-grained igneous rock, with one rhyolite piece; cores include recurrent centripetal and preferential Levallois forms.","sig":"Documents tool-making from local rock along an ancient drainage system.","ex":"Groucutt et al. (2016)","disc":["Local igneous stone","Levallois cores"],"refs":["Groucutt, H.S. et al. (2016). The Middle Palaeolithic of the Nejd, Saudi Arabia. Journal of Field Archaeology 41(2), 131–147. https://doi.org/10.1080/00934690.2016.1156928"],"conf":"Not numerically dated in the source; placed within the broad Middle Palaeolithic span used for other undated Arabian sites. Coordinates about ±1 km","ev":"","an":"","val":""},{"id":"dawadmi-23","n":"Dawadmi-23 (DWD-23)","na":"الدوادمي 23 (DWD-23)","c":"archaeological","ic":"trench","era":"P","s":"Stone Age quarry beside a microgranite dyke","lat":24.8956,"lng":43.5408,"p":"Lower and Middle Palaeolithic","dr":"Middle Palaeolithic, with older Lower Palaeolithic finds","el":"Low-density scatter by a felsic dyke","t0":100000,"t1":55000,"te":"A rock wall that became a toolbox","ta":"جدار صخري صار صندوق أدوات","se":"A natural wall of fine microgranite supplied stone for Levallois tools, about 90 km north-west of Dawadmi","sa":"جدار طبيعي من المايكروجرانيت الناعم زوّد الإنسان بحجر للأدوات اللوفالوازية، على بعد نحو 90 كم شمال غرب الدوادمي","desc":"A Middle Palaeolithic site beside a felsic igneous dyke about 90 km north-west of Dawadmi. The dyke’s fine-grained microgranite was good for making tools. A low-density scatter of Middle Palaeolithic artefacts lies close to the dyke, with Lower Palaeolithic material on the lower slope; Levallois cores and flakes show several stages of working.","sig":"Evidence of prehistoric people using igneous dykes as stone sources.","ex":"Groucutt et al. (2016)","disc":["Microgranite dyke source","Lower Palaeolithic finds too"],"refs":["Groucutt, H.S. et al. (2016). The Middle Palaeolithic of the Nejd, Saudi Arabia. Journal of Field Archaeology 41(2), 131–147. https://doi.org/10.1080/00934690.2016.1156928"],"conf":"Not numerically dated in the source; placed within the broad Middle Palaeolithic span used for other undated Arabian sites. Coordinates about ±1 km","ev":"","an":"","val":""},{"id":"jebel-abyad-1","n":"Jebel Abyad-1 (ABY-1)","na":"جبل أبيض 1 (ABY-1)","c":"archaeological","ic":"trench","era":"P","s":"Stone Age tools on a white quartz hill","lat":24.2608,"lng":44.4927,"p":"Lower and Middle Palaeolithic","dr":"Middle Palaeolithic, with probable Lower Palaeolithic handaxes","el":"Quartz exposure on the summit","t0":100000,"t1":55000,"te":"The white hill of quartz","ta":"التل الأبيض من الكوارتز","se":"An isolated hill of white quartz where Stone Age people shaped tools on the slopes","sa":"تل منعزل من الكوارتز الأبيض شكّل إنسان العصر الحجري أدواته على سفوحه","desc":"An isolated hill of white quartz with a large exposure at its summit and eroded fragments on its slopes. A low-density concentration of Middle Palaeolithic quartz artefacts lies part-way up the slope, with a few probable Lower Palaeolithic handaxes nearby. The tools show preferential Levallois flaking with centripetal preparation, and discoidal technology.","sig":"Shows prehistoric use of natural quartz sources and tools adapted to local stone.","ex":"Groucutt et al. (2016)","disc":["Quartz tools","Probable handaxes"],"refs":["Groucutt, H.S. et al. (2016). The Middle Palaeolithic of the Nejd, Saudi Arabia. Journal of Field Archaeology 41(2), 131–147. https://doi.org/10.1080/00934690.2016.1156928"],"conf":"Not numerically dated in the source; placed within the broad Middle Palaeolithic span used for other undated Arabian sites. Coordinates about ±1 km","ev":"","an":"","val":""},{"id":"qasim-shaghab-outcrop","n":"Qasim Formation outcrop (Shaghab)","na":"مكشف تكوين القصيم (شغب)","c":"geological","ic":"cliff","era":"D","s":"Ordovician sandstone baked by basalt sills","lat":27.7638,"lng":36.5853,"p":"Middle–Late Ordovician","dr":"Middle–Late Ordovician","el":"Two sections about 400 m apart","t0":470000000,"t1":443800000,"te":"Sandstone cooked by lava","ta":"حجر رملي طبخته الحمم","se":"Ancient sea-shore sandstone south of Tabuk, changed where hot basalt pushed in above it","sa":"حجر رملي من شاطئ بحر قديم جنوب تبوك، تغيّر حيث اندفع البازلت الساخن فوقه","desc":"About 50 km south of Tabuk in the Shaghab quadrangle, this outcrop exposes Middle to Upper Ordovician shallow-marine sandstones of the Qasim Formation (Quwarah Member). Basaltic sills above the sandstone altered it near the contact: petrographic, mineral and chemical analyses found dissolved quartz, changed carbonate cements and transformed clay minerals. Two shallow sections about 400 m apart were measured.","sig":"A natural laboratory for how magma changes sandstone and its quality as a reservoir rock.","ex":"Bello et al. (2023)","disc":["Basalt sills over sandstone","Contact alteration of minerals"],"refs":["Bello, A.M.A. et al. (2023). Impact of magmatic intrusion on diagenesis of shallow marine sandstones: An example from Qasim Formation, Northwest Saudi Arabia. Frontiers in Earth Science 11. https://doi.org/10.3389/feart.2023.1105547"],"conf":"Numeric ages are the standard span of the Middle–Late Ordovician. Coordinates about ±1 km","ev":"","an":"","val":""},{"id":"wadi-sharma-1","n":"Wadi Sharma 1","na":"وادي شرما 1","c":"archaeological","ic":"wall","era":"P","s":"First fully excavated early Neolithic village in Saudi Arabia","lat":28.0962,"lng":35.4823,"p":"Pre-Pottery Neolithic B","dr":"Second half of the 8th millennium BC (14 radiocarbon dates)","el":"About 60 linked stone structures over 0.1 ha","t0":9500,"t1":9000,"te":"A village of sixty rooms","ta":"قرية من ستين غرفة","se":"A string of about 60 stone rooms where early herders camped by season, 9,500 years ago","sa":"سلسلة من نحو 60 غرفة حجرية خيّم فيها رعاة أوائل موسميًا قبل 9500 سنة","desc":"A Neolithic settlement in Tabuk Province on the northern edge of a valley plain about 25 km upstream from the mouth of Wadi Sharma. Excavation revealed about 60 ground-level or semi-sunken masonry structures joined into an elongated settlement of about 0.1 ha, with chipped stone tools, grinding stones and shell ornaments. Fourteen radiocarbon dates place it in the second half of the 8th millennium cal BC; it is seen as a small, seasonally occupied community.","sig":"The first fully excavated Pre-Pottery Neolithic B settlement in Saudi Arabia, linking north-west Arabia with the southern Levant.","ex":"Fujii et al. (2018), Atlal 26","disc":["About 60 stone structures","14 radiocarbon dates"],"refs":["Fujii, S., al-Mansoor, A.A., Adachi, T., al-Khalifa, K.A., Nagaya, K. & al-Anazi, A.S. (2018). Preliminary Excavation Report of Wadi Sharma 1, a Neolithic Settlement in the Tabuk Province (2012–2013). Atlal 26. https://heritage.moc.gov.sa/-/media/Project/Ministries/Commission/heritage/Etlal-files1/atlal-26.pdf"],"conf":"The source writes the coordinates as \"28.05.463, 035.28.561\"; read another way the pin could move about 0.7 km","ev":"","an":"","val":""},{"id":"al-uyaynah-neolithic","n":"Al Uyaynah Neolithic settlement","na":"مستوطنة العيينة النيوليثية","c":"archaeological","ic":"wall","era":"P","s":"Early farming hamlet north of Tabuk with 200 clay objects","lat":28.8944,"lng":36.0733,"p":"Late Pre-Pottery Neolithic B","dr":"About 7190–6900 cal BC","el":"Remains over about 160 × 120 m","t0":9190,"t1":8900,"te":"The hill of little clay figures","ta":"تل التماثيل الطينية الصغيرة","se":"Early herders kept sheep and goats on a hill north of Tabuk and left more than 200 small clay objects","sa":"رعاة أوائل ربّوا الأغنام والماعز على تل شمال تبوك وتركوا أكثر من 200 قطعة طينية صغيرة","desc":"A Neolithic settlement about 70 km north of Tabuk on a low sandstone hill above an alluvial plain and seasonal wadi. Surface remains cover about 160 × 120 m, with rectangular stone buildings on the hilltop and circular or curved ones lower on the slope. Excavation found stone tools, animal bones showing sheep and goat herding, and more than 200 small clay objects. Radiocarbon dating places the main occupation at about 7190–6900 cal BC.","sig":"A short-lived Late Pre-Pottery Neolithic B settlement with herding, possible cultivation and distinctive clay objects.","ex":"Alasmari et al. (2026)","disc":["Over 200 clay objects","Sheep and goat herding"],"refs":["Alasmari, K., Piper, S.F., Grothe, K., Hamilton, W.D., Joly, D., Bickle, P. & Bailey, G. (2026). New Results From the Pre-Pottery Neolithic Site of Al Uyaynah, Tabuk, in Northwestern Saudi Arabia. Arabian Archaeology and Epigraphy 37(1), 182–206. https://doi.org/10.1111/aae.70021"],"conf":"","ev":"","an":"","val":""},{"id":"jabal-rayah","n":"Jabal Rayah ring structure","na":"الحلقة الصخرية في جبل رية","c":"geological","ic":"quake","era":"D","s":"A 5.5 km stone ring – possibly an ancient impact crater","lat":28.65,"lng":37.2,"p":"Age unknown","dr":"Younger than its Palaeozoic host rocks; not dated","el":"Ring about 5.5 km wide, crest about 150 m high","t0":541000000,"t1":0,"te":"A ring that may have fallen from the sky","ta":"حلقة ربما سقطت من السماء","se":"A 5.5 km ring of hills north-east of Tabuk that scientists think may be the root of a meteorite crater","sa":"حلقة من التلال عرضها 5.5 كم شمال شرق تبوك يرى العلماء أنها ربما جذر فوهة نيزكية","desc":"A ring-shaped structure about 5.5 km wide north-east of Tabuk in flat-lying Palaeozoic sandstones and other clastic rocks. Erosion has inverted the relief, leaving a ring crest about 150 m high around a worn-down centre. Mapping found displaced blocks, folds, faults and thrusts, which led researchers to propose a possible complex impact origin; diagnostic impact evidence such as shocked quartz or impact melt has not been confirmed.","sig":"A key Saudi site for testing how to tell impact craters from other ring structures.","ex":"Gnos et al. (2018)","disc":["Ring about 5.5 km wide","Impact origin proposed, not proven"],"refs":["Gnos, E. et al. (2018). Sandstone sample analysis and additional structural data from Jabal Rayah, a possible impact structure in Saudi Arabia. Meteoritics & Planetary Science 53(12), 2652–2660. https://doi.org/10.1111/maps.13187"],"conf":"Age unknown; the timeline span runs from the start of the Palaeozoic (era of the host rocks) to today. Coordinates about ±1 km","ev":"","an":"","val":""},{"id":"harrat-uwayrid","n":"Harrat Uwayrid Biosphere Reserve","na":"محمية المحيط الحيوي حرة عويرض","c":"ecology","ic":"plant","era":"N","s":"UNESCO biosphere reserve of lava, sandstone and oasis","lat":27.01,"lng":37.52,"p":"Present","dr":"UNESCO Biosphere Reserve 2022","el":"About 762,700 ha","t0":4,"t1":0,"te":"Where lava meets the oasis","ta":"حيث تلتقي الحمم بالواحة","se":"A huge AlUla reserve of volcanic fields, sandstone mountains and an oasis valley, being restored with native wildlife","sa":"محمية واسعة في العلا تضم حقولًا بركانية وجبالًا من الحجر الرملي ووادي واحة، يُعاد تأهيلها بالأحياء الأصلية","desc":"A UNESCO biosphere reserve in the AlUla region of north-western Saudi Arabia covering about 762,700 ha of hot-desert biome. Its landscape combines volcanic terrain, sandstone mountains and an oasis valley. The reserve supports restoration of native plants and animals, research on ecosystem functions and traditional land use, and study of its geological formations and landforms.","sig":"A large protected landscape where desert life, volcanic and sandstone landforms, oasis ecosystems and people can be studied together.","ex":"UNESCO Man and the Biosphere Programme","disc":["About 762,700 ha","Native species restoration"],"refs":["UNESCO (2022). Harrat Uwayrid Biosphere Reserve. Man and the Biosphere Programme. https://www.unesco.org/en/mab/harrat-uwayrid"],"conf":"Pin is the reserve’s general location (about ±10 km)","ev":"","an":"","val":""},{"id":"ras-suwayhil-l0006","n":"Ras Suwayhil el Kabir (L0006)","na":"رأس سويحل الكبير (L0006)","c":"archaeological","ic":"trench","era":"P","s":"Handaxes on a raised coral shore of the Gulf of Aqaba","lat":28.6796,"lng":34.782,"p":"Lower Palaeolithic (Acheulean)","dr":"Acheulean; terrace possibly the last interglacial high sea (MIS 5e)","el":"Cliffs about 40 m; coral heads about 25 m above sea level","t0":500000,"t1":130000,"te":"Handaxes on an old coral beach","ta":"فؤوس يدوية على شاطئ مرجاني قديم","se":"Acheulean handaxes lie on a coral terrace now 25 m above the sea, left when sea level was higher","sa":"فؤوس يدوية أشولية على مصطبة مرجانية ترتفع الآن 25 م فوق البحر، تكوّنت حين كان البحر أعلى","desc":"A raised coastal terrace at Ras Suwayhil el Kabir where coral and alluvial deposits are exposed in cliffs about 40 m high. Fossil-rich sands and coral heads reach about 25 m above sea level and may belong to the Marine Isotope Stage 5e high sea stand. Survey recorded Acheulean handaxes and other artefacts of quartzite and indurated shale; 47 artefacts were listed, many concentrated in a 10 × 5 m patch. Excavation and dating are still needed.","sig":"Joins early human tools with a raised shoreline record useful for reconstructing past sea levels.","ex":"Inglis et al. (2019)","disc":["Acheulean handaxes","Raised coral terrace"],"refs":["Inglis, R.H., Sinclair, A., Alsharekh, A., Scott, C. & Al Otaibi, D. (2019). The Palaeolithic of the northern Red Sea – new investigations in Tabuk and Al-Jawf provinces, Saudi Arabia. Proceedings of the Seminar for Arabian Studies 49, 167–186. https://eprints.whiterose.ac.uk/id/eprint/159308/"],"conf":"Not dated in the source; the timeline span is a broad Arabian Acheulean estimate","ev":"","an":"","val":""},{"id":"ifal-l0011","n":"Ifal Depression hogbacks (L0011)","na":"منخفض عفال (L0011)","c":"archaeological","ic":"trench","era":"P","s":"Stone Age tools and pecked cobbles on eroded ridges","lat":28.3143,"lng":34.9364,"p":"Middle Stone Age to Upper Palaeolithic; later pecked stones","dr":"Middle Stone Age and Upper Palaeolithic; pecked cobbles possibly Thamudic","el":"Tilted Tertiary hogback ridges","t0":100000,"t1":20000,"te":"Ridges that uncover the past","ta":"حواف تكشف الماضي","se":"Erosion of tilted ridges in the Ifal Depression exposes Stone Age tools and three cobbles with pecked designs","sa":"تآكل الحواف المائلة في منخفض عفال يكشف أدوات العصر الحجري وثلاث حصوات عليها نقوش منقورة","desc":"A locality on Tertiary hogback ridges in the Ifal Depression, a landscape of tilted sedimentary rocks shaped by uneven erosion. Survey recorded stone tools classed as Middle Stone Age and Upper Palaeolithic, and three rounded cobbles with pecked designs thought possibly Thamudic in age. The date of the designs is uncertain.","sig":"Shows repeated human activity in the Ifal Depression over a long span.","ex":"Inglis et al. (2019)","disc":["Middle Stone Age and Upper Palaeolithic tools","Three pecked cobbles"],"refs":["Inglis, R.H., Sinclair, A., Alsharekh, A., Scott, C. & Al Otaibi, D. (2019). The Palaeolithic of the northern Red Sea – new investigations in Tabuk and Al-Jawf provinces, Saudi Arabia. Proceedings of the Seminar for Arabian Studies 49, 167–186. https://eprints.whiterose.ac.uk/id/eprint/159308/"],"conf":"Not dated in the source; the timeline span is a broad estimate for the tool types","ev":"","an":"","val":""},{"id":"wadi-sharma-l0025","n":"Wadi Sharma cairn row (L0025)","na":"صف الركام الجنائزي في وادي شرما (L0025)","c":"archaeological","ic":"mound","era":"P","s":"A row of burial cairns on a coastal terrace","lat":27.8612,"lng":35.5871,"p":"Undated cairns; Middle Stone Age tools","dr":"Cairns undated; three Middle Stone Age artefacts","el":"12 artefacts recorded","t0":100000,"t1":55000,"te":"Graves lined up on the terrace","ta":"قبور مصطفّة على المصطبة","se":"A line of stone burial cairns on a terrace between Al Khuraybah and Al Muwaylih, beside older stone tools","sa":"صف من الركام الحجري الجنائزي على مصطبة بين الخريبة والمويلح، بجانب أدوات حجرية أقدم","desc":"An alluvial terrace in the coastal landscape between Al Khuraybah and Al Muwaylih where survey documented a row of funerary cairns and 12 stone artefacts, three classed as Middle Stone Age. The age and culture of the cairns were not established by the survey. About 27 km from the excavated Neolithic village of Wadi Sharma 1.","sig":"A burial landscape alongside prehistoric tools, showing repeated use of coastal terraces.","ex":"Inglis et al. (2019)","disc":["Row of funerary cairns","Middle Stone Age artefacts"],"refs":["Inglis, R.H., Sinclair, A., Alsharekh, A., Scott, C. & Al Otaibi, D. (2019). The Palaeolithic of the northern Red Sea – new investigations in Tabuk and Al-Jawf provinces, Saudi Arabia. Proceedings of the Seminar for Arabian Studies 49, 167–186. https://eprints.whiterose.ac.uk/id/eprint/159308/"],"conf":"The cairns are undated; the timeline position follows the Middle Stone Age artefacts and is an estimate","ev":"","an":"","val":""},{"id":"spec-khaybar-waystations","n":"Lava Tubes as Waystations between the Mustatils","c":"speculative","s":"Cross-category hypothesis","lat":25.64,"lng":39.55,"p":"Neolithic","dr":"c. 8000–5000 BC (test window)","el":"","desc":"A connection between records on this map. Umm Jirsan, a 1.5 km lava tube in Harrat Khaybar, was used again and again by cattle, sheep and goat herders from about 10,000 to 7,000 years ago, and its entrance carries rock art of herders with dogs. The same lava fields hold mustatils, the long stone rectangles where cattle herders of about 5300–5000 BC placed horns around a standing stone. Harrat Khaybar has a 100 km vent system and many more tubes that have never been excavated. The idea: the tubes formed a chain of cool, wind-free waystations along the routes herders walked between pastures, water and the mustatils, so that occupied tubes should cluster along those routes and share the herders’ dates.","sig":"If true, the hundreds of unexcavated lava tubes of the harrats would be a buried archive of the Neolithic herders who built the mustatils, and the routes between monuments could be mapped from the caves instead of guessed.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Dates: Umm Jirsan occupation c. 10,000–7,000 years ago and into the Bronze Age (Stewart et al. 2024); mustatil offerings c. 5300–5000 BC (Thomas et al. 2021). Animals: cattle, sheep and goats in the cave bones; cattle, sheep and gazelle horns in the mustatil chamber. Proximity: Umm Jirsan (25.586 N, 39.754 E) lies within the same Harrat Khaybar lava field as mustatils recorded at about 25.7 N, 39.3 E, some 45 km apart. Later the Khaybar oasis held the Bronze Age town of Al-Natah (2400–1300 BC), and the cave diets gained fruit and cereals when oasis farming arrived.","an":"In the Mediterranean, caves used as seasonal sheepfolds by Neolithic herders leave characteristic burnt dung layers (fumiers); Brochier and colleagues (1992) showed from Sicily and southern France that such cave deposits record repeated short stays on pastoral routes rather than permanent homes.","val":"Survey the entrances of lava tubes along transects between known mustatils in Harrat Khaybar; test-pit the floors of tubes with surface finds; radiocarbon-date charcoal and bone; identify herd animals from bone and dung; compare the dates and species with the mustatil chambers; map occupied tubes against distances to water and monuments.","disc":["Rival explanation 1: tubes were used opportunistically wherever they happened to be, with no relation to routes or monuments.","Rival explanation 2: occupation of Umm Jirsan is unusual, and most tubes were too dark, unstable or far from water to be used.","Rival explanation 3: the cave users and the mustatil builders were different groups separated by centuries, and the animals only look similar."],"refs":["Stewart, M., Andrieux, E., Blinkhorn, J. et al. (2024). First evidence for human occupation of a lava tube in Arabia. PLOS ONE 19(4).","Thomas, H., Kennedy, M. A., Dalton, M. et al. (2021). The mustatils: cult and monumentality in Neolithic north-western Arabia. Antiquity 95(381), 605–626.","Kennedy, M. A. et al. (2023). Cult, herding and pilgrimage in the Late Neolithic of north-west Arabia. PLOS ONE 18(3).","Smithsonian Institution Global Volcanism Program. Harrat Khaybar.","Brochier, J. E., Villa, P., Giacomarra, M. & Tagliacozzo, A. (1992). Shepherds and sediments: geo-ethnoarchaeology of pastoral sites. Journal of Anthropological Archaeology 11(1), 47–102."],"ic":"spark","era":"?","te":"Did herders use the lava caves as a chain of shelters?","ta":"هل استخدم الرعاة كهوف الحمم سلسلة ملاجئ؟","se":"The herders who slept in Umm Jirsan kept the same animals as the people who built the mustatils in the same lava field. Were the lava tubes a chain of shelters along their routes? Nobody has tested this yet.","sa":"الرعاة الذين ناموا في أم جرسان ربّوا الحيوانات نفسها التي ربّاها من بنوا المستطيلات في الحَرّة نفسها. فهل كانت أنابيب الحمم سلسلة ملاجئ على طرقهم؟ لم يختبر أحد ذلك بعد.","na":"أنابيب الحمم محطات بين المستطيلات","t0":10000,"t1":7000,"spec":{"bas":"link","key":"waystation","sty":"ai-waystation","spot":{"en":"Born from two records in one lava field on this map. Umm Jirsan was used by cattle, sheep and goat herders from about 10,000 years ago; 45 km away, mustatil builders of about 5300–5000 BC offered cattle, sheep and gazelle horns. Same animals, same harrat, overlapping centuries, and hundreds of other tubes nobody has dug.","ar":"وُلدت الفكرة من سجلين في حَرّة واحدة على هذه الخريطة: استخدم رعاة الأبقار والأغنام والماعز أم جرسان منذ نحو 10,000 عام؛ وعلى بعد 45 كيلومترًا قدّم بناة المستطيلات نحو 5300–5000 ق.م قرون أبقار وأغنام وغزلان. الحيوانات نفسها، والحَرّة نفسها، وقرون متداخلة، ومئات الأنابيب الأخرى لم يحفرها أحد."},"lk":[["umm-jirsan","The excavated tube: herders, dogs and 10,000-year-old fires","الأنبوب المنقَّب: رعاة وكلاب ونيران عمرها 10,000 عام"],["mustatils","The monuments of the same cattle herders, c. 5300–5000 BC","صروح رعاة الأبقار أنفسهم، نحو 5300–5000 ق.م"],["harrat-khaybar-white-volcanoes","The lava field that made the tubes","حقل الحمم الذي صنع الأنابيب"],["al-natah-khaybar","The oasis town that came after, and the cereals in the cave diets","بلدة الواحة التي جاءت بعدُ، والحبوب في غذاء أهل الكهف"]],"pred":{"en":"Lava tubes within a day’s walk of mustatils and water will hold hearths and herd-animal bones with radiocarbon dates overlapping 5300–5000 BC, while tubes far from both will be empty.","ar":"ستحوي أنابيب الحمم الواقعة على مسيرة يوم من المستطيلات والماء مواقد وعظام حيوانات قطيع بتواريخ كربونية تتداخل مع 5300–5000 ق.م، بينما تكون الأنابيب البعيدة عن كليهما فارغة."},"test":{"en":"Walk transects between mustatils, record every tube entrance, test-pit the promising ones, date the charcoal and identify the bones; then compare occupied tubes with distance to monuments and water.","ar":"المشي في مسارات بين المستطيلات، وتسجيل كل مدخل أنبوب، وحفر اختبارات في الواعدة منها، وتأريخ الفحم وتحديد العظام؛ ثم مقارنة الأنابيب المسكونة بالمسافة إلى الصروح والماء."},"wrong":{"en":"If occupied tubes are scattered at random, or their dates never overlap the mustatil centuries, or Umm Jirsan proves to be the only one used, the chain-of-waystations idea fails.","ar":"إذا كانت الأنابيب المسكونة مبعثرة عشوائيًا، أو لم تتداخل تواريخها مع قرون المستطيلات أبدًا، أو ثبت أن أم جرسان الوحيد المستخدم، تسقط فكرة سلسلة المحطات."}}},{"id":"spec-jubbah-lake-art","n":"The Jubbah Lake and the Changing Pictures","c":"speculative","s":"Cross-category hypothesis","lat":28.3,"lng":40.5,"p":"Early–Middle Holocene","dr":"c. 8000–3000 BC (test window)","el":"","desc":"A connection between records on this map. At Jubbah, the rock art of Jabal Umm Sinman stands above the bed of a Holocene lake about 20 by 5 km; the oldest carvings of life-size people and wild animals are about 10,000 years old, and later panels show cattle herding, then horses and camels. About 200 km north-west, the Columns of Rajajil, standing stones of the sixth to fifth millennium BC, have wells dug beside them. To the south, mustatil builders of about 5300–5000 BC were cattle herders of a wetter Arabia. The idea: the sequence of pictures at Jubbah tracks the life of the lake, with wild-animal panels made while it held water, cattle panels as it shrank to pasture, and wells and camels after it was gone.","sig":"If true, the rock art of Ha’il could be read as a dated climate record, and the lake sediments could date the panels that have no inscriptions.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Dates and places: oldest Jubbah carvings c. 10,000 years ago, palaeolake 20 × 5 km at Jubbah (UNESCO 2015; Guagnin et al. 2017); mustatil cattle offerings c. 5300–5000 BC about 250 km south; Rajajil stones with fifth-millennium BC wells about 200 km north-west. Content: the panels change from wild animals (aurochs, kudu, wild ass) to domestic cattle to horses and camels, the order expected if water fell and herding then dry-land travel took over.","an":"In the Sahara, Kuper and Kröpelin (2006) showed from hundreds of dated sites that human occupation, cattle herding and rock art followed the rains southward as the Green Sahara dried between about 8500 and 3500 BC; the Eastern Sahara’s cattle-herder panels belong to the wet phase, and settlement left when the lakes failed.","val":"Core the Jubbah lake bed and date its layers (radiocarbon, OSL) to fix when it held water, shrank and dried; date the rock-art panels by their varnish, superimposition and the animals they show; compare the two timelines; check whether the Rajajil wells were dug just when the regional lakes failed.","disc":["Rival explanation 1: the pictures changed because new animals and new people arrived, not because the lake changed.","Rival explanation 2: the lake dried much earlier than the cattle panels, and herders used wells from the start.","Rival explanation 3: the carvings were made from ridges above the lake bed at any time, with no link to its water level."],"refs":["UNESCO World Heritage Centre. Rock Art in the Hail Region of Saudi Arabia (ref. 1472), inscribed 2015.","Guagnin, M. et al. (2017). Rock art provides new evidence on the biogeography of kudu, wild dromedary, aurochs and African wild ass in the early and middle Holocene of north-western Arabia. Journal of Biogeography 44, 2071–2081.","Thomas, H., Kennedy, M. A., Dalton, M. et al. (2021). The mustatils: cult and monumentality in Neolithic north-western Arabia. Antiquity 95(381), 605–626.","Kuper, R. & Kröpelin, S. (2006). Climate-controlled Holocene occupation in the Sahara: motor of Africa’s evolution. Science 313(5788), 803–807."],"ic":"spark","era":"?","te":"Did the rock art change as the lake dried?","ta":"هل تغيرت الصور الصخرية مع جفاف البحيرة؟","se":"The pictures at Jubbah go from wild animals to cattle to camels, carved above a lake that dried. Does the order of the art follow the water? Nobody has tested this yet.","sa":"تنتقل الصور في جبة من حيوانات برية إلى أبقار إلى جمال، منقوشة فوق بحيرة جفّت. فهل يتبع ترتيب الفن الماءَ؟ لم يختبر أحد ذلك بعد.","na":"بحيرة جبة والصور المتغيرة","t0":10000,"t1":5000,"spec":{"bas":"link","key":"lake","sty":"ai-lake","spot":{"en":"Born from a lake bed and a cliff on this map. Jubbah’s oldest carvings, about 10,000 years old, show wild animals above a lake 20 by 5 km; later panels show cattle, then camels. To the south, cattle herders built mustatils around 5300–5000 BC; to the north-west, people dug wells beside the Rajajil stones in the fifth millennium BC. Water first, then herds, then wells.","ar":"وُلدت الفكرة من قاع بحيرة وجرف على هذه الخريطة. تُظهر أقدم نقوش جبة، وعمرها نحو 10,000 عام، حيوانات برية فوق بحيرة طولها 20 كيلومترًا وعرضها 5؛ وتُظهر اللوحات اللاحقة أبقارًا ثم جمالًا. وإلى الجنوب بنى رعاة الأبقار المستطيلات نحو 5300–5000 ق.م؛ وإلى الشمال الغربي حفر الناس آبارًا بجوار أحجار الرجاجيل في الألف الخامس ق.م. الماء أولًا، ثم القطعان، ثم الآبار."},"lk":[["hail-rock-art","The carvings above the vanished lake, 10,000 years of pictures","النقوش فوق البحيرة المختفية، 10,000 عام من الصور"],["mustatils","The cattle herders of a wetter Arabia, c. 5300–5000 BC","رعاة الأبقار في جزيرة عربية أكثر مطرًا، نحو 5300–5000 ق.م"],["rajajil-columns","Standing stones with fifth-millennium BC wells beside them","أحجار قائمة وبجوارها آبار من الألف الخامس ق.م"],["umm-jirsan","Rock art of herders with dogs in the same wetter centuries","فن صخري لرعاة مع كلاب في القرون الرطبة نفسها"]],"pred":{"en":"Cores from the Jubbah lake bed will show open water during the centuries of the wild-animal panels, shallow or seasonal water during the cattle panels, and a dry bed before the horse and camel panels and the first wells.","ar":"ستُظهر عينات قاع بحيرة جبة ماءً مفتوحًا خلال قرون لوحات الحيوانات البرية، وماءً ضحلًا أو موسميًا خلال لوحات الأبقار، وقاعًا جافًا قبل لوحات الخيل والجمال والآبار الأولى."},"test":{"en":"Core and date the lake sediments; date the panels by varnish, overlap and species; lay the two timelines side by side and see whether the changes in the art fall at the changes in the water.","ar":"أخذ عينات لبية من رواسب البحيرة وتأريخها؛ وتأريخ اللوحات بالطلاء الصخري والتراكب والأنواع؛ ووضع الخطين الزمنيين جنبًا إلى جنب لمعرفة ما إذا كانت تغيرات الفن تقع عند تغيرات الماء."},"wrong":{"en":"If the lake was already dry when the wild-animal panels were carved, or stayed full through the cattle and camel panels, the art did not follow the water and the idea fails.","ar":"إذا كانت البحيرة جافة أصلًا حين نُقشت لوحات الحيوانات البرية، أو ظلت ممتلئة طوال لوحات الأبقار والجمال، فلم يتبع الفنُّ الماءَ وتسقط الفكرة."}}},{"id":"spec-dome-springs","n":"The Folds that Hold Oil and Lift Water","c":"speculative","s":"Cross-category hypothesis","lat":25.9,"lng":49.8,"p":"Neolithic to Hellenistic","dr":"c. 5000 BC – AD 300 (test window)","el":"","desc":"A connection between records on this map. The Dammam Dome, where well No. 7 struck oil in 1938, is a salt-cored anticline; Ghawar, 200 km east of Riyadh, follows the En Nala anticline on a basement horst, sealed by anhydrite. Al-Ahsa, farmed since the Neolithic, is watered by more than 280 artesian springs from the Neogene aquifer, and Jabal Al-Qarah beside it is cut by deep joint-controlled fissures. Tarout Island has been inhabited since about 5000 BC and Thaj, a walled city of 300 BC–AD 300, lies between them. The idea: the same folds and joints that trap oil at depth bend and crack the shallow aquifer, forcing water up as springs, so that the oldest settlements of the Arabian Gulf coast sit on the crests and flanks of these structures.","sig":"If true, the deep geology that made the kingdom’s oil also decided where its first farmers and traders could live, and new springs or old ones could be predicted from structural maps.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Structures: Dammam Dome, a salt-cored anticline (Dammam No. 7 record); Ghawar on the En Nala anticline, 280 km long, sealed by 30–100 m of anhydrite. Water: more than 280 artesian springs at Al-Ahsa from the Neogene aquifer; joint-controlled fissures in the Hofuf Formation at Jabal Al-Qarah (Hussain et al. 2006). Settlement: Al-Ahsa farmed since the Neolithic; Tarout inhabited since c. 5000 BC with Ubaid pottery of c. 4500 BC; Thaj walled city c. 300 BC–AD 300. Geography: Al-Ahsa (25.43 N, 49.62 E) lies about 40 km west of the Ghawar crest; Tarout (26.57 N, 50.06 E) about 30 km north of the Dammam Dome.","an":"On Bahrain, Larsen (1983) showed that the island’s famous artesian springs rise where the Dammam aquifer is bent and fractured over the Bahrain dome, and that the Dilmun settlements and burial fields of the third and second millennia BC clustered on exactly those spring lines, moving as the springs did.","val":"Overlay spring locations at Al-Ahsa, Qatif and Tarout on the mapped crests and faults of the Dammam Dome and En Nala anticline; measure artesian pressure and water chemistry along and off the structures; date early settlement layers at Tarout, Al-Ahsa and Thaj and compare with spring positions; look for fossil spring mounds and tufa along fold axes.","disc":["Rival explanation 1: the springs rise where the aquifer simply reaches the surface at low ground, with no relation to folds.","Rival explanation 2: settlements followed the coast, the sea and trade, and springs were a bonus rather than the reason.","Rival explanation 3: rainfall far inland on the Tuwaiq outcrop controls the artesian pressure, and the folds only add small local effects."],"refs":["Saudi Aramco. Dammam No. 7: the Prosperity Well.","Afifi, A. M. (2004). Ghawar: the anatomy of the world's largest oil field. AAPG Search and Discovery.","UNESCO World Heritage Centre. Al-Ahsa Oasis, an Evolving Cultural Landscape (ref. 1563), inscribed 2018.","Hussain, M., Al-Khalifah, F. & Khandaker, N. I. (2006). The Jabal Al Qarah caves of the Hofuf area, northeastern Saudi Arabia: a geological investigation. Journal of Cave and Karst Studies 68(1), 12–21.","Wikipedia contributors (2026). Tarout Island, citing Bibby, G. (1969) Looking for Dilmun.","Larsen, C. E. (1983). Life and Land Use on the Bahrain Islands: The Geoarchaeology of an Ancient Society. University of Chicago Press."],"ic":"spark","era":"?","te":"Do the oil-trapping folds also feed the oasis springs?","ta":"هل تغذي طيّات النفط ينابيع الواحة أيضًا؟","se":"The folds that hold the oil under Dammam and Ghawar may be the same folds that push 280 springs to the surface at Al-Ahsa, where people have farmed for 7,000 years. Nobody has tested this yet.","sa":"قد تكون الطيّات التي تحبس النفط تحت الدمام والغوار هي نفسها التي تدفع 280 ينبوعًا إلى السطح في الأحساء، حيث يزرع الناس منذ 7,000 عام. لم يختبر أحد ذلك بعد.","na":"الطيّات التي تحبس النفط وترفع الماء","t0":7000,"t1":1700,"spec":{"bas":"link","key":"springs","sty":"ai-springs","spot":{"en":"Born from three records that sit close together on this map. Dammam No. 7 found oil in a salt-cored dome; Ghawar follows a long anticline; between and beside them, Al-Ahsa’s 280 artesian springs have fed farms since the Neolithic and Tarout has been lived on since 5000 BC. Oil needs a fold to trap it. Springs may need the same fold to lift them.","ar":"وُلدت الفكرة من ثلاثة سجلات متقاربة على هذه الخريطة. وجدت بئر الدمام رقم 7 النفط في قبة ذات نواة ملحية؛ ويتبع الغوار طيّة طويلة؛ وبينهما وبجوارهما تغذي ينابيع الأحساء الـ280 المزارع منذ العصر الحجري الحديث، وتُسكن تاروت منذ 5000 ق.م. النفط يحتاج إلى طيّة تحبسه. وقد تحتاج الينابيع إلى الطيّة نفسها لترفعها."},"lk":[["dammam-no-7","A salt-cored dome that trapped oil at 1,440 m","قبة ذات نواة ملحية حبست النفط على عمق 1,440 مترًا"],["ghawar-field","The En Nala anticline, 280 km long, sealed by anhydrite","طيّة النالة المحدبة، طولها 280 كيلومترًا، مختومة بالأنهيدريت"],["al-ahsa-oasis","More than 280 artesian springs and 7,000 years of farming","أكثر من 280 ينبوعًا ارتوازيًا و7,000 عام من الزراعة"],["jabal-al-qarah-caves","Deep joints that crack the same rocks beside the oasis","شقوق عميقة تكسر الصخور نفسها بجوار الواحة"],["tarout-island","Lived on since 5000 BC, 30 km from the Dammam Dome","مسكونة منذ 5000 ق.م، على بعد 30 كيلومترًا من قبة الدمام"]],"pred":{"en":"Springs, fossil spring mounds and the oldest settlement layers will line up along the mapped crests and faults of the Dammam Dome and the En Nala anticline, and artesian pressure will be highest there.","ar":"ستصطف الينابيع وتلال الينابيع الأحفورية وأقدم طبقات الاستيطان على طول قمم وصدوع قبة الدمام وطيّة النالة المرسومة على الخرائط، وسيكون الضغط الارتوازي أعلى ما يكون هناك."},"test":{"en":"Map every spring and fossil spring mound against the structural contours; measure pressure and chemistry on and off the folds; date the earliest layers at Tarout, Al-Ahsa and Thaj and see whether they sit on spring lines.","ar":"رسم كل ينبوع وتل ينبوع أحفوري على خطوط الكنتور البنيوية؛ وقياس الضغط والكيمياء فوق الطيّات وبعيدًا عنها؛ وتأريخ أقدم الطبقات في تاروت والأحساء وثاج لمعرفة ما إذا كانت تقع على خطوط الينابيع."},"wrong":{"en":"If springs and early settlements are spread evenly across low ground regardless of the folds, or pressure is no higher on the crests, the structural idea fails.","ar":"إذا كانت الينابيع والمستوطنات المبكرة موزعة بانتظام على الأراضي المنخفضة بصرف النظر عن الطيّات، أو لم يكن الضغط أعلى على القمم، تسقط الفكرة البنيوية."}}},{"id":"spec-najd-stone-sources","n":"Rock Outcrops as a Map of Stone Age Camps","c":"speculative","s":"Cross-category hypothesis","lat":24.55,"lng":44.3,"p":"Middle Palaeolithic","dr":"Middle Palaeolithic (test window)","el":"","desc":"A connection between records on this map. Across the Najd and the southern Nefud, every Middle Palaeolithic site in this layer sits on a particular kind of rock: Dawadmi-23 beside a dyke of fine microgranite, Jebel Abyad-1 on a hill of white quartz, Az Zu’aynah-2 next to bedrock on the edge of a braided wadi, Al Qana-1 on an alluvial fan full of rhyolite, and Jebel Umm Sanman-1 at Jubbah with its yellow quartzite. At several of them tools were made on the spot. The idea: Middle Palaeolithic toolmakers chose places where good-quality rock met water, so the geological map of dykes, quartz and rhyolite near old drainage lines should predict where undiscovered sites lie.","sig":"If true, geological maps of Saudi Arabia, already complete, could guide surveys straight to the most likely Stone Age sites across thousands of square kilometres.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Rock: DWD-23 (24.90 N, 43.54 E) lies beside a felsic dyke of fine-grained microgranite; ABY-1 (24.26 N, 44.49 E) on a white quartz hill with a summit exposure; AZA-2 (24.35 N, 44.99 E) close to bedrock exposures on floodplain margins (Groucutt et al. 2016). QAN-1 (27.77 N, 41.41 E) is dominated by rhyolite, with on-site tool production (Groucutt et al. 2016). JSM-1 (27.98 N, 40.92 E) used a distinctive yellow quartzite (Petraglia et al. 2012). Water: AZA-2 borders a wadi braidplain; QAN-1 lies on an alluvial fan; JSM-1 overlooks the Jubbah palaeolake. Distances: ABY-1 to AZA-2 about 50 km, DWD-23 to ABY-1 about 120 km. Dates: only nearby JQ-1 at Jubbah is numerically dated (211–75 thousand years).","an":"In Dhofar, southern Oman, Rose and colleagues (2011) recorded more than 100 surface sites with Nubian Middle Palaeolithic tools on the plateau, many of them workshops at outcrops of chert, and dated one of them, Aybut Al Auwal, to about 106,000 years ago.","val":"Digitise dykes, quartz veins and rhyolite from the Saudi geological maps; trace old drainage lines from satellite images; divide the Najd into equal survey cells and rank them by rock and water; survey high-ranked and low-ranked cells with teams who do not know the ranking; compare the number of Middle Palaeolithic sites found in each.","disc":["Rival explanation 1: survey bias — archaeologists looked near outcrops, so that is where they found sites.","Rival explanation 2: random foraging alone can produce links between tools and rock sources (Brantingham 2003).","Rival explanation 3: tools survive and show best where bedrock is near the surface, not where people preferred to camp."],"refs":["Groucutt, H.S. et al. (2016). The Middle Palaeolithic of the Nejd, Saudi Arabia. Journal of Field Archaeology 41(2), 131–147.","Petraglia, M.D. et al. (2012). Hominin dispersal into the Nefud Desert and Middle Palaeolithic settlement along the Jubbah palaeolake, northern Arabia. PLOS ONE 7(11), e49840.","Rose, J.I. et al. (2011). The Nubian Complex of Dhofar, Oman: an African Middle Stone Age industry in southern Arabia. PLOS ONE 6(11), e28239.","Brantingham, P.J. (2003). A neutral model of stone raw material procurement. American Antiquity 68(3), 487–509."],"ic":"spark","era":"?","te":"Can a geological map find lost Stone Age sites?","ta":"هل تستطيع خريطة جيولوجية أن تجد مواقع العصر الحجري المفقودة؟","se":"Five Stone Age sites on this map each sit on a special rock: a dyke, a quartz hill, rhyolite, yellow quartzite. Could a geological map point to the sites nobody has found yet? Nobody has tested this yet.","sa":"خمسة مواقع من العصر الحجري على هذه الخريطة يقع كل منها على صخر مميز: قاطع صخري، وتل كوارتز، وريوليت، وكوارتزيت أصفر. فهل تستطيع خريطة جيولوجية أن تدلّنا على مواقع لم يجدها أحد بعد؟ لم يختبر أحد ذلك بعد.","na":"المكاشف الصخرية خريطة لمخيمات العصر الحجري","t0":100000,"t1":55000,"spec":{"bas":"link","key":"stonemap","sty":"ai-stonemap","spot":{"en":"Born from five records on this map. Each Middle Palaeolithic site in the Najd and southern Nefud lies on good tool-making rock — microgranite, quartz, rhyolite or quartzite — and several sit beside old wadis, a fan or a lake, with tools made on the spot.","ar":"وُلدت الفكرة من خمسة سجلات على هذه الخريطة: كل موقع من العصر الحجري القديم الأوسط في نجد وجنوب النفود يقع على صخر جيد لصنع الأدوات — مايكروجرانيت أو كوارتز أو ريوليت أو كوارتزيت — وعدة منها بجانب أودية قديمة أو مروحة فيضية أو بحيرة، وقد صُنعت الأدوات في المكان نفسه."},"lk":[["dawadmi-23","Tools beside a dyke of fine microgranite","أدوات بجانب قاطع من المايكروجرانيت الناعم"],["jebel-abyad-1","A hill of white quartz used for tools","تل من الكوارتز الأبيض استُخدم للأدوات"],["az-zuaynah-2","Local igneous rock at the edge of a braided wadi","صخر ناري محلي على حافة وادٍ متشعب"],["al-qana-1","Rhyolite worked on an alluvial fan","ريوليت مشغول على مروحة فيضية"],["jebel-umm-sanman-jsm1","Yellow quartzite cores above the Jubbah lake","نوى من الكوارتزيت الأصفر فوق بحيرة جبة"]],"pred":{"en":"Survey cells where fine-grained rock lies within a couple of kilometres of an old wadi will hold several times more Middle Palaeolithic sites than equal cells without such rock.","ar":"ستحوي خلايا المسح التي يقع فيها صخر ناعم الحبيبات على بعد كيلومترين تقريبًا من وادٍ قديم مواقع من العصر الحجري القديم الأوسط أكثر بعدة مرات من خلايا مماثلة بلا هذا الصخر."},"test":{"en":"Rank survey cells from the geological map, then send teams who do not know the ranking to walk both high- and low-ranked cells and count the sites.","ar":"ترتيب خلايا المسح من الخريطة الجيولوجية، ثم إرسال فرق لا تعرف الترتيب للمشي في الخلايا العالية والمنخفضة الترتيب وعدّ المواقع."},"wrong":{"en":"If low-ranked cells yield as many sites as high-ranked ones, the rock-and-water map has no power and the idea fails.","ar":"إذا أعطت الخلايا المنخفضة الترتيب عددًا من المواقع مماثلًا للعالية، فلا قيمة لخريطة الصخر والماء وتسقط الفكرة."}}},{"id":"spec-kites-terrain","n":"The Land Shapes the Kite","c":"speculative","s":"Cross-category hypothesis","lat":22.36,"lng":41.2,"p":"Prehistoric","dr":"Undated kites (test window)","el":"","desc":"A connection between records on this map. Two lava fields 360 km apart hold desert kites, stone walls that funnelled wild animals into pens. In Harrat Kishb, more than 20 kites have shallower guiding-wall angles than those of Harrat Khaybar, and their builders worked the natural relief into the design. In Harrat Nawasif, several hundred kites cluster on the lava margins and around small wadis, mostly with two gently converging walls and simple end enclosures; one is 1.4 km long. The idea: kite design was set mainly by the terrain — where slopes and lava edges already steered animals, builders shaped the walls differently — so wall angle and length should follow the local relief more than the region or the people.","sig":"If true, kite plans could be read as a record of how prehistoric hunters used the landform, and the thousands of kites across Arabia could be compared on one scale instead of being sorted into separate cultures.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Kishb: more than 20 kites; shallower guiding-wall angles than Harrat Khaybar kites; natural topography incorporated; several building phases (UNESCO Tentative List 2023). Nawasif: several hundred kites along the lava-field margins and small wadis, on old west-to-east drainage; most with two gently converging walls and simple terminal enclosures; one about 1,400 m long with about 3,000 m of walls enclosing more than 500,000 m² (UNESCO Tentative List 2023). Al Wahbah crater lies in the same Harrat Kishb about 56 km south-south-west of the Kishb kite component. None of these kites is dated in the records.","an":"At Tell Kuran in north-eastern Syria, Bar-Oz, Zeder and Hole (2011) studied a huge deposit of Persian gazelle bones from the mass killing of whole herds about 5,000 years ago, and linked it to desert kites set across the routes of migrating gazelles; Crassard and colleagues (2022) later reviewed the evidence that kites worked as mega-traps.","val":"Map every kite in Harrat Kishb, Harrat Nawasif and Harrat Khaybar from high-resolution satellite images; measure guiding-wall angle, wall length and enclosure size; compute slope, relief and distance to lava edge and wadis around each kite from elevation data; test whether the shape measures follow terrain the same way in all three fields; date wall phases where possible.","disc":["Rival explanation 1: the differences reflect different builders, traditions or periods; Kishb has several building phases.","Rival explanation 2: the kites targeted different animals whose herds moved differently.","Rival explanation 3: walls were repaired and rebuilt, so their present angles show later changes, not the first design."],"refs":["Permanent Delegation of Saudi Arabia to UNESCO (2023). Prehistoric Stone Structures in Saudi Arabia. UNESCO World Heritage Tentative List, ref. 6636.","Bar-Oz, G., Zeder, M. & Hole, F. (2011). Role of mass-kill hunting strategies in the extirpation of Persian gazelle (Gazella subgutturosa) in the northern Levant. PNAS 108(18), 7345–7350.","Crassard, R. et al. (2022). The use of desert kites as hunting mega-traps: functional evidence and potential impacts on socioecological systems. Journal of Archaeological Method and Theory."],"ic":"spark","era":"?","te":"Did the lava, not the builders, decide the shape of the desert kites?","ta":"هل حدّدت الحمم، لا البناة، شكل مصائد الصحراء؟","se":"Kites in two lava fields look different: Kishb’s walls hug the slopes, Nawasif’s are long simple funnels by the wadis. Did the land decide the shape? Nobody has tested this yet.","sa":"تبدو المصائد في حرّتين مختلفة: جدران كشب تحتضن المنحدرات، وجدران النواصف أقماع طويلة بسيطة عند الأودية. فهل حدّدت الأرض الشكل؟ لم يختبر أحد ذلك بعد.","na":"الأرض تشكّل المصيدة","t0":9000,"t1":5000,"spec":{"bas":"link","key":"kites","sty":"ai-kites","spot":{"en":"Born from two records on this map. The Kishb kites use the natural relief and have shallower wall angles than Khaybar’s; the hundreds of Nawasif kites line the lava margins and small wadis with simple converging walls. Two harrats, two shapes, two terrains.","ar":"وُلدت الفكرة من سجلين على هذه الخريطة: مصائد كشب تستغل التضاريس الطبيعية وزوايا جدرانها أضيق من مصائد خيبر؛ ومئات مصائد النواصف تصطف على حواف الحمم والأودية الصغيرة بجدران متقاربة بسيطة. حرّتان، وشكلان، وتضاريس مختلفة."},"lk":[["harrat-kishb-kites","Kites that use the natural relief","مصائد تستغل التضاريس الطبيعية"],["harrat-nawasif-kites","Hundreds of simple funnels by the wadis","مئات الأقماع البسيطة عند الأودية"],["harrat-khaybar-white-volcanoes","The lava field whose kites are the comparison","حقل الحمم الذي تُقارن مصائده"],["al-wahbah-crater","The crater in the same Harrat Kishb","الفوهة في حرة كشب نفسها"]],"pred":{"en":"Across all three lava fields, kites on steeper, more broken ground will show the same shift in wall angle and wall length, whatever field they are in.","ar":"في الحرّات الثلاث ستُظهر المصائد على الأرض الأشد انحدارًا والأكثر تقطعًا التغيّر نفسه في زاوية الجدران وطولها، أيًّا كانت الحرّة."},"test":{"en":"Measure every kite from satellite images and the ground around it from elevation data, then check whether shape follows terrain the same way in each field.","ar":"قياس كل مصيدة من صور الأقمار الصناعية وقياس الأرض حولها من بيانات الارتفاع، ثم التحقق من أن الشكل يتبع التضاريس بالطريقة نفسها في كل حرّة."},"wrong":{"en":"If kites on similar ground in different fields still differ strongly, or shape shows no link to slope at all, the land is not the main designer and the idea fails.","ar":"إذا بقيت المصائد على أرض متشابهة في حرّات مختلفة متباينة بشدة، أو لم يرتبط الشكل بالانحدار أبدًا، فليست الأرض هي المصمم الرئيسي وتسقط الفكرة."}}},{"id":"spec-ppn-seasonal-round","n":"Two Villages, One Year?","c":"speculative","s":"Archaeological hypothesis","lat":28.5,"lng":35.78,"p":"Pre-Pottery Neolithic B","dr":"c. 7500–6900 BC (test window)","el":"","desc":"A connection between records on this map. Wadi Sharma 1, about 25 km up a valley that opens to the Red Sea, is a cluster of about 60 linked stone rooms with shell ornaments, dated by 14 radiocarbon dates to the second half of the 8th millennium BC and seen as seasonally occupied. Al Uyaynah, about 106 km to the north-east on the Tabuk plateau, is a small, short-lived settlement of sheep and goat herders with more than 200 clay objects, dated to about 7190–6900 BC. The two sets of dates overlap, and the Hisma mountain corridor lies between them. The idea: these were not two separate communities but two seasonal stops of the same mobile herders, who moved between the coastal valleys and the plateau through the year.","sig":"If true, the earliest herding communities of north-west Arabia lived by a yearly round across very different landscapes, and their small sites should be read as parts of one system rather than as isolated villages.","ex":"","conf":"Untested AI speculation (connection between published records)","ev":"Wadi Sharma 1 (28.10 N, 35.48 E): about 60 ground-level or semi-sunken stone structures over about 0.1 ha; chipped stone, grinding stones and shell ornaments; 14 radiocarbon dates in the second half of the 8th millennium cal BC; interpreted as a small, seasonally occupied community (Fujii et al. 2018). Al Uyaynah (28.89 N, 36.07 E): remains over about 160 × 120 m; sheep and goat husbandry; more than 200 small clay objects; main occupation about 7190–6900 cal BC; small and short-lived (Alasmari et al. 2026). Distance between them about 106 km; the Hisma stone-structure corridor lies about 44 km from Wadi Sharma 1 and 62 km from Al Uyaynah. JQ-101 at Jubbah shows Pre-Pottery Neolithic activity further east.","an":"In the south-western Cape of South Africa, Balasse and colleagues (2002) read the oxygen and carbon isotopes in growth bands of sheep teeth, which record where and in which season an animal grazed, to test whether prehistoric herders moved their flocks between the coast and the interior through the year.","val":"Sample sheep and goat teeth from Al Uyaynah, and any herd-animal teeth from Wadi Sharma 1, for sequential oxygen and carbon isotope analysis; identify the shell ornaments at both sites and trace them to the Red Sea or elsewhere; compare stone-tool and clay-object styles; look for seasonal markers in plant remains and animal ages; survey the Hisma corridor for camps of the same date.","disc":["Rival explanation 1: two separate communities living in their own areas who never met.","Rival explanation 2: one group moved once, from one place to the other, rather than every year.","Rival explanation 3: Al Uyaynah was used year-round for a short time, and seasonality there is not needed."],"refs":["Fujii, S. et al. (2018). Preliminary excavation report of Wadi Sharma 1, a Neolithic settlement in the Tabuk Province (2012–2013). Atlal 26.","Alasmari, K. et al. (2026). New results from the Pre-Pottery Neolithic site of Al Uyaynah, Tabuk, in north-western Saudi Arabia. Arabian Archaeology and Epigraphy 37(1), 182–206.","Balasse, M., Ambrose, S.H., Smith, A.B. & Price, T.D. (2002). The seasonal mobility model for prehistoric herders in the south-western Cape of South Africa assessed by isotopic analysis of sheep tooth enamel. Journal of Archaeological Science 29(9), 917–932.","Permanent Delegation of Saudi Arabia to UNESCO (2023). Prehistoric Stone Structures in Saudi Arabia. UNESCO World Heritage Tentative List, ref. 6636."],"ic":"spark","era":"?","te":"Were the valley and plateau villages two seasons of the same herders?","ta":"هل كانت قرية الوادي وقرية الهضبة موسمين لرعاة واحد؟","se":"A seasonal village in a Red Sea valley and a short-lived herders’ village on the Tabuk plateau were lived in during the same centuries, about 100 km apart. Were they one people’s summer and winter homes? Nobody has tested this yet.","sa":"قرية موسمية في وادٍ على البحر الأحمر وقرية رعاة قصيرة العمر على هضبة تبوك سُكنتا في القرون نفسها، على بعد نحو 100 كم. فهل كانتا بيتي الصيف والشتاء لشعب واحد؟ لم يختبر أحد ذلك بعد.","na":"قريتان، سنة واحدة؟","t0":9500,"t1":8900,"spec":{"bas":"link","key":"seasons","sty":"ai-seasons","spot":{"en":"Born from two records on this map. Wadi Sharma 1 was a seasonal village of the late 8th millennium BC with shell ornaments; Al Uyaynah, 106 km away, was a short-lived herders’ village of about 7190–6900 BC. Overlapping dates, one mountain corridor between them.","ar":"وُلدت الفكرة من سجلين على هذه الخريطة: كانت وادي شرما 1 قرية موسمية من أواخر الألف الثامن ق.م بحلي صدفية؛ وكانت العيينة، على بعد 106 كم، قرية رعاة قصيرة العمر نحو 7190–6900 ق.م. تواريخ متداخلة، وممر جبلي واحد بينهما."},"lk":[["wadi-sharma-1","The seasonal valley village with shell ornaments","قرية الوادي الموسمية ذات الحلي الصدفية"],["al-uyaynah-neolithic","The short-lived plateau village of sheep and goat herders","قرية الهضبة القصيرة العمر لرعاة الأغنام والماعز"],["hisma-stone-structures","The mountain corridor between the two","الممر الجبلي بينهما"],["jebel-qattar-jq101","Pre-Pottery Neolithic activity further east at Jubbah","نشاط من العصر الحجري الحديث ما قبل الفخار شرقًا في جبة"]],"pred":{"en":"Growth bands in herd-animal teeth from Al Uyaynah will show grazing that switches between plateau and lowland conditions with the seasons, and Red Sea shells will turn up among its finds.","ar":"ستُظهر حلقات النمو في أسنان حيوانات القطيع من العيينة رعيًا يتبدل بين ظروف الهضبة والأراضي المنخفضة مع الفصول، وستظهر أصداف من البحر الأحمر بين لقاها."},"test":{"en":"Run sequential isotope analysis on sheep and goat teeth, identify the shells at both sites, and compare tools and clay objects between them.","ar":"إجراء تحليل نظائر متسلسل على أسنان الأغنام والماعز، وتحديد الأصداف في الموقعين، ومقارنة الأدوات والقطع الطينية بينهما."},"wrong":{"en":"If the teeth show animals grazing in one place all year, and the two sites share no shells or styles, the two-season idea fails.","ar":"إذا أظهرت الأسنان حيوانات ترعى في مكان واحد طوال العام، ولم يشترك الموقعان في أصداف أو أساليب، تسقط فكرة الموسمين."}}}],"stops":[]})}catch(e){console.error("D",String(e).slice(0,80))}
